(425600, 38989, 10084, '<td valign="top">The darker color of the spider really makes it pop out of the picture. The green of the background really helps with this. Pretty good details in the spider. You can see all the individual hairs. Don''t really like the frame too much. It blends in too much with the black of the spider.</td>', 'The darker color of the spider really makes it pop out of the picture. The green of the background really helps with this. Pretty good details in the spider. You can see all the individual hairs. Don''t really like the frame too much. It blends in too much with the black of the spider.', '2003-09-22 04:30:07.000000', NULL, 1),
(425601, 38721, 10084, '<td valign="top">Beautiful details in the iguana. Absolutely incredible shadows and lighting reflections help to bring them out. You can almost feel the texture of the skin. Great depth of field really makes it pop out of the picture and feels alive.</td>', 'Beautiful details in the iguana. Absolutely incredible shadows and lighting reflections help to bring them out. You can almost feel the texture of the skin. Great depth of field really makes it pop out of the picture and feels alive.', '2003-09-22 04:32:08.000000', NULL, 1),
(425602, 38924, 10084, '<td valign="top">Love the closeup of the denim. Every shadow and light reflections make you feel the texture of the denim. You can see the weave of the denim. I would have like a bit more light on the zipper itself. Seems kind of dark.</td>', 'Love the closeup of the denim. Every shadow and light reflections make you feel the texture of the denim. You can see the weave of the denim. I would have like a bit more light on the zipper itself. Seems kind of dark.', '2003-09-22 04:34:02.000000', NULL, 1),
(425603, 39006, 10084, '<td valign="top">Love the beautiful colors in the broach. Great lighting. Love the way that each of the round marble shaped items have the ring of light. The black background really helps to lift this off the page.</td>', 'Love the beautiful colors in the broach. Great lighting. Love the way that each of the round marble shaped items have the ring of light. The black background really helps to lift this off the page.', '2003-09-22 04:37:07.000000', NULL, 1),
(425604, 39005, 10084, '<td valign="top">Incredible details. All the shadows and reflections off the fur is captured very well and gives a great sense of furriness. The green background really brings the subject forward. Love the reflections in the eyes. Really like the hair lifting up and highlighted by the green background. The flys cool too.</td>', 'Incredible details. All the shadows and reflections off the fur is captured very well and gives a great sense of furriness. The green background really brings the subject forward. Love the reflections in the eyes. Really like the hair lifting up and highlighted by the green background. The flys cool too.', '2003-09-22 04:39:41.000000', NULL, 1),
(425605, 38537, 10084, '<td valign="top">Really nice details enhanced by the great shadows and reflections. Beautiful shapes in the picture.</td>', 'Really nice details enhanced by the great shadows and reflections. Beautiful shapes in the picture.', '2003-09-22 04:41:19.000000', NULL, 1),
(425607, 38972, 8860, '<td valign="top">Lovely detail. Shame about the slight movement of the second hand - would be better either totally frozen or even longer exposure to show more movement.</td>', 'Lovely detail. Shame about the slight movement of the second hand - would be better either totally frozen or even longer exposure to show more movement.', '2003-09-22 04:45:30.000000', NULL, 1),
(425608, 38868, 10084, '<td valign="top">Beautiful autumn colors. Incredible details in the leaf. The shadows and reflections show the veins of the leaf. It gives you a sense of the texture of the leaf itself. The black background really makes the leaf pop out of the shot.</td>', 'Beautiful autumn colors. Incredible details in the leaf. The shadows and reflections show the veins of the leaf. It gives you a sense of the texture of the leaf itself. The black background really makes the leaf pop out of the shot.', '2003-09-22 04:46:40.000000', NULL, 1),
(425609, 38804, 8860, '<td valign="top">Beautiful capture. You''ve managed a great shot (even with some flash?) with lots of detail and great colour. Cute little fella too. [8]</td>', 'Beautiful capture. You''ve managed a great shot (even with some flash?) with lots of detail and great colour. Cute little fella too. [8]', '2003-09-22 04:47:16.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(425610, 38409, 8860, '<td valign="top">Cute idea and a lovely little snake. Shame about the time code and the softness of the focus. A little Unsharp mask would have helped. Good composition.</td>', 'Cute idea and a lovely little snake. Shame about the time code and the softness of the focus. A little Unsharp mask would have helped. Good composition.', '2003-09-22 04:48:37.000000', NULL, 1),
(425611, 38873, 10084, '<td valign="top">The focusing really makes the subject pop out of the shot. The subject need a bit more sharpening or a least a closer shot. Difficult to see some of the details.</td>', 'The focusing really makes the subject pop out of the shot. The subject need a bit more sharpening or a least a closer shot. Difficult to see some of the details.', '2003-09-22 04:49:10.000000', NULL, 1),
(425612, 38010, 8860, '<td valign="top">Love the design here - startling colours and dynamics. Very good composition, concept and lighting. One for the wall for sure. [10]</td>', 'Love the design here - startling colours and dynamics. Very good composition, concept and lighting. One for the wall for sure. [10]', '2003-09-22 04:50:07.000000', NULL, 1),
(425624, 38134, 10084, '<td valign="top">Absolutely beautiful colors. Love the contrast of the yellow and the blue. The reflections on the bubble are simply stunning. Makes them really pop out of the shot. Good depth of field helps to separate foreground bubbles from background ones. Framing really works here.</td>', 'Absolutely beautiful colors. Love the contrast of the yellow and the blue. The reflections on the bubble are simply stunning. Makes them really pop out of the shot. Good depth of field helps to separate foreground bubbles from background ones. Framing really works here.', '2003-09-22 05:03:09.000000', NULL, 1),
(425625, 38877, 12075, '<td valign="top">this is so touching..great composition..so original...my favorite<br/> <br/>WELL DONE!!!</td>', 'this is so touching..great composition..so original...my favorite WELL DONE!!!', '2003-09-22 05:04:51.000000', NULL, 1),
(425626, 38754, 8860, '<td valign="top">I see what you''re trying to achieve here but you needed some rough stuff in focus. I would also have tried to fill the frame with that material too as the surrounding background is not helpful. Lighting from one side (rather than above, middle) would also prevent the glaring central highlight and create more atmosphere.</td>', 'I see what you''re trying to achieve here but you needed some rough stuff in focus. I would also have tried to fill the frame with that material too as the surrounding background is not helpful. Lighting from one side (rather than above, middle) would also prevent the glaring central highlight and create more atmosphere.', '2003-09-22 05:05:23.000000', NULL, 1),
(425627, 37882, 8860, '<td valign="top">That''s a pitcher plant isn''t it? Flash is a bit harsh directional lighting would have helped. Great plant.</td>', 'That''s a pitcher plant isn''t it? Flash is a bit harsh directional lighting would have helped. Great plant.', '2003-09-22 05:06:32.000000', NULL, 1),
(425628, 38476, 8860, '<td valign="top">Fantastic. Great detail. <br/> <br/>I never tire of the insect world. Ever. [8]</td>', 'Fantastic. Great detail.  I never tire of the insect world. Ever. [8]', '2003-09-22 05:07:49.000000', NULL, 1),
(425636, 38914, 1829, '<td valign="top">An excellent shot.  It''s a simple image, yet very effective.  The red, black and silver all blend in very well.  I also like the dof.  Again an excellent macro shot and well done!!!</td>', 'An excellent shot.  It''s a simple image, yet very effective.  The red, black and silver all blend in very well.  I also like the dof.  Again an excellent macro shot and well done!!!', '2003-09-22 06:40:25.000000', NULL, 1),
(425644, 38425, 1829, '<td valign="top">Very nice!!  The whole picture really ''grabs'' the eye.  The shadows are just awesome and I love how it blends in with the background.  The watch with the hand clutching it tells me that ''time is precious'' in other words - clench onto life.  Clarity and the closeness of your photo is very pleasing and clear to see.  Your photograph is just brilliant.  GL in this weeks challenge.</td>', 'Very nice!!  The whole picture really ''grabs'' the eye.  The shadows are just awesome and I love how it blends in with the background.  The watch with the hand clutching it tells me that ''time is precious'' in other words - clench onto life.  Clarity and the closeness of your photo is very pleasing and clear to see.  Your photograph is just brilliant.  GL in this weeks challenge.', '2003-09-22 06:49:54.000000', NULL, 1),
(425645, 38760, 1829, '<td valign="top">Reds, greens and yellows is what is appealing about your photograph.  All colours blend in really well.  Nicely done and gl in this weeks challenge.</td>', 'Reds, greens and yellows is what is appealing about your photograph.  All colours blend in really well.  Nicely done and gl in this weeks challenge.', '2003-09-22 06:51:22.000000', NULL, 1),
(425646, 38959, 1829, '<td valign="top">Composition is brilliant, it captures the essence of the whole photograph.  The colour is awesome as well.  Nice job and gl in this weeks challenge.</td>', 'Composition is brilliant, it captures the essence of the whole photograph.  The colour is awesome as well.  Nice job and gl in this weeks challenge.', '2003-09-22 06:52:59.000000', NULL, 1),
(425648, 38868, 1829, '<td valign="top">A beautiful image.  The colours and simplicity of your photograph is lovely.  Very well done and GL in this weeks challenge.</td>', 'A beautiful image.  The colours and simplicity of your photograph is lovely.  Very well done and GL in this weeks challenge.', '2003-09-22 06:54:54.000000', NULL, 1),
(425654, 38793, 1829, '<td valign="top">I just love this (even though it makes me cringe lol).  Clarity is perfect, even down to the web itself.  I just love the colours in the dof, makes the photo look fresh and welcoming.  Overall a great photograph which deserves a high score!!!</td>', 'I just love this (even though it makes me cringe lol).  Clarity is perfect, even down to the web itself.  I just love the colours in the dof, makes the photo look fresh and welcoming.  Overall a great photograph which deserves a high score!!!', '2003-09-22 06:59:47.000000', NULL, 1),
(425656, 38134, 1829, '<td valign="top">Now this is very creative!!  I love the blues, yellows and all those bubbles.  Clarity is brilliant as well.  Nicely done and gl in this weeks challenge.</td>', 'Now this is very creative!!  I love the blues, yellows and all those bubbles.  Clarity is brilliant as well.  Nicely done and gl in this weeks challenge.', '2003-09-22 07:01:47.000000', NULL, 1),
(425658, 38278, 200, '<td valign="top">excellent title...nice shadows</td>', 'excellent title...nice shadows', '2003-09-22 07:02:23.000000', NULL, 1),
(425660, 38474, 200, '<td valign="top">erotic</td>', 'erotic', '2003-09-22 07:03:33.000000', NULL, 1),
(425662, 38568, 1829, '<td valign="top">A lovely photograph.  I love the setting and the dof.  The ring and the colours all blend in very well.  The only hot spot is the white glare on the left of the image.  Overall a lovely image, well done and gl in this weeks challenge.</td>', 'A lovely photograph.  I love the setting and the dof.  The ring and the colours all blend in very well.  The only hot spot is the white glare on the left of the image.  Overall a lovely image, well done and gl in this weeks challenge.', '2003-09-22 07:04:25.000000', NULL, 1),
(425668, 38878, 1829, '<td valign="top">LOL - Love the title.  The overall image is brilliant.  Clarity, colours and dof are just awesome and what a great find!!!  The composition is really appealing to the eye in the way the stick insect has positioned itself on the tree.  Excellent image and GL in this weeks challenge.</td>', 'LOL - Love the title.  The overall image is brilliant.  Clarity, colours and dof are just awesome and what a great find!!!  The composition is really appealing to the eye in the way the stick insect has positioned itself on the tree.  Excellent image and GL in this weeks challenge.', '2003-09-22 07:06:52.000000', NULL, 1),
(425672, 38642, 200, '<td valign="top">at first glance...i thought this was a pill...such as prozac...now that would have been funny!</td>', 'at first glance...i thought this was a pill...such as prozac...now that would have been funny!', '2003-09-22 07:09:45.000000', NULL, 1),
(425682, 38655, 772, '<td valign="top">Greetings... This is a great shot.  This is the kind of ''abstract'' that I like in photography.  The subject itself is not abstract but the theme behind it is.  This looks like a giant hand of divine nature reaching out from within the cosmos and grabbing an unsuspecting planet :)  Very nice work :) = 10</td>', 'Greetings... This is a great shot.  This is the kind of ''abstract'' that I like in photography.  The subject itself is not abstract but the theme behind it is.  This looks like a giant hand of divine nature reaching out from within the cosmos and grabbing an unsuspecting planet :)  Very nice work :) = 10', '2003-09-22 07:22:07.000000', NULL, 1),
(425687, 39007, 772, '<td valign="top">Greetings... I love an integration of traditional art and photography.  The ''traditional'' arts are something that I wish I could do.  I have no skill with my own hands when it comes to drawing, painting, or sculpting.  I suppose this type of photograph makes me realize that even more.  I can ''see'' it but I can''t move the thought to another medium with my hands... great shot :) = 10</td>', 'Greetings... I love an integration of traditional art and photography.  The ''traditional'' arts are something that I wish I could do.  I have no skill with my own hands when it comes to drawing, painting, or sculpting.  I suppose this type of photograph makes me realize that even more.  I can ''see'' it but I can''t move the thought to another medium with my hands... great shot :) = 10', '2003-09-22 07:24:34.000000', NULL, 1),
(425695, 38283, 1368, '<td valign="top">Is it frosen? Very hairy! Very cool :)</td>', 'Is it frosen? Very hairy! Very cool :)', '2003-09-22 07:29:06.000000', NULL, 1),
(425697, 38963, 772, '<td valign="top">Greetings... This photo gets a 10 for technical excellence :)</td>', 'Greetings... This photo gets a 10 for technical excellence :)', '2003-09-22 07:30:08.000000', NULL, 1),
(425698, 38665, 772, '<td valign="top">Greetings... This photo gets a 10 for technical excellence :)  Good work with the closeup view :)</td>', 'Greetings... This photo gets a 10 for technical excellence :)  Good work with the closeup view :)', '2003-09-22 07:30:39.000000', NULL, 1),
(425701, 38134, 772, '<td valign="top">Greetings :)  This photo is simply ''refreshing'' to my eye.  The sound of the the carbonation and the scent of the lemon combine nicely in this photo.  Since this image is  visually appealing and stirring senses other than vision, I think it''s a great photograph :)  This is one of the few photos I have seen recently that appeal to multiple senses this way.  "Touch" is the only sense that I have trouble relating to this shot.  It''s not always natural to want to reach out and touch something wet.  Excellent work... = 10</td>', 'Greetings :)  This photo is simply ''refreshing'' to my eye.  The sound of the the carbonation and the scent of the lemon combine nicely in this photo.  Since this image is  visually appealing and stirring senses other than vision, I think it''s a great photograph :)  This is one of the few photos I have seen recently that appeal to multiple senses this way.  "Touch" is the only sense that I have trouble relating to this shot.  It''s not always natural to want to reach out and touch something wet.  Excellent work... = 10', '2003-09-22 07:40:16.000000', NULL, 1),
(425716, 38857, 10128, '<td valign="top">Very nice, 10</td>', 'Very nice, 10', '2003-09-22 08:05:32.000000', NULL, 1),
(425723, 37882, 7889, '<td valign="top">The flash is way to harsh and spoils the photo</td>', 'The flash is way to harsh and spoils the photo', '2003-09-22 08:29:30.000000', NULL, 1),
