(425733, 38678, 7889, '<td valign="top">Good effort, i like ths shadow very much<br/></td>', 'Good effort, i like ths shadow very much', '2003-09-22 08:37:29.000000', NULL, 1),
(425734, 38283, 11738, '<td valign="top">Superfly!  Hmmm... this looks awful familiar.  I love this shot because it''s not head on like most of the other insect macros we often see.  Furthermore, the depth of field is very good, letting us see much of the fly''s body in focus.  You can even see the fly''s small secondary pair of wings.  A definite 10 and in my book the challenge winner.</td>', 'Superfly!  Hmmm... this looks awful familiar.  I love this shot because it''s not head on like most of the other insect macros we often see.  Furthermore, the depth of field is very good, letting us see much of the fly''s body in focus.  You can even see the fly''s small secondary pair of wings.  A definite 10 and in my book the challenge winner.', '2003-09-22 08:38:54.000000', NULL, 1),
(425735, 38179, 7889, '<td valign="top">Too blurry, but a good idea</td>', 'Too blurry, but a good idea', '2003-09-22 08:38:57.000000', NULL, 1),
(425738, 38425, 7889, '<td valign="top">Good use of B&amp;W, excellent clarity and very original.</td>', 'Good use of B&W, excellent clarity and very original.', '2003-09-22 08:55:41.000000', NULL, 1),
(425742, 38763, 7889, '<td valign="top">This is way too messy,focus is not good and subject is overexposed, background is not good.</td>', 'This is way too messy,focus is not good and subject is overexposed, background is not good.', '2003-09-22 09:01:09.000000', NULL, 1),
(425743, 38134, 7889, '<td valign="top">Vibrant colours, great idea, sharp focus. i like it!</td>', 'Vibrant colours, great idea, sharp focus. i like it!', '2003-09-22 09:02:06.000000', NULL, 1),
(425747, 38996, 7543, '<td valign="top">The edges seem a bit jagged, looks unnatural. The crop is great and the subject is a classic. 6</td>', 'The edges seem a bit jagged, looks unnatural. The crop is great and the subject is a classic. 6', '2003-09-22 09:15:32.000000', NULL, 1),
