(425749, 38409, 7543, '<td valign="top">Great concept. Only thing (and I guess you hear this alot) I see wrong with this shot is the timestamp, might be impossible to remove it? I would have zoomed out a bit and crop the timestamp away.</td>', 'Great concept. Only thing (and I guess you hear this alot) I see wrong with this shot is the timestamp, might be impossible to remove it? I would have zoomed out a bit and crop the timestamp away.', '2003-09-22 09:18:50.000000', NULL, 1),
(425750, 38994, 7543, '<td valign="top">Great colors</td>', 'Great colors', '2003-09-22 09:19:21.000000', NULL, 1),
