(425782, 38966, 11800, '<td valign="top">Like the comp and that it''s b/w, would have gotten a better score if at least one part of the image was in sharp focus with a little more light on the right.</td>', 'Like the comp and that it''s b/w, would have gotten a better score if at least one part of the image was in sharp focus with a little more light on the right.', '2003-09-22 10:03:25.000000', NULL, 1),
(425792, 38283, 8159, '<td valign="top">Wow! This is amazingly close! The hairs on the back of the bug are disturbingly gross! Great shot. Excellent control of reflections on the fly; I''ve taken bug macros before and their highly-reflective body/eyes make them a pain to shoot! Awesome job!</td>', 'Wow! This is amazingly close! The hairs on the back of the bug are disturbingly gross! Great shot. Excellent control of reflections on the fly; I''ve taken bug macros before and their highly-reflective body/eyes make them a pain to shoot! Awesome job!', '2003-09-22 10:13:42.000000', NULL, 1),
(425794, 38727, 8624, '<td valign="top">moving the subject farther away from the background will reduce the harsh shadows.</td>', 'moving the subject farther away from the background will reduce the harsh shadows.', '2003-09-22 10:16:08.000000', NULL, 1),
(425795, 38895, 8624, '<td valign="top">I like the closeup of the gdoll''s face, but the arm portion without any wrist or hand details is distracting.</td>', 'I like the closeup of the gdoll''s face, but the arm portion without any wrist or hand details is distracting.', '2003-09-22 10:16:55.000000', NULL, 1),
