(425813, 38677, 8624, '<td valign="top">I like the choice of B&amp;W for this shot and I think the shallow DOF works pretty well.</td>', 'I like the choice of B&W for this shot and I think the shallow DOF works pretty well.', '2003-09-22 10:28:31.000000', NULL, 1),
(425814, 38011, 92, '<td valign="top">Very unique for this week ! I love the DOF and the rich color. The compostion is great ! Wonderful textures and contrast.  10</td>', 'Very unique for this week ! I love the DOF and the rich color. The compostion is great ! Wonderful textures and contrast.  10', '2003-09-22 10:28:46.000000', NULL, 1),
(425815, 38971, 8624, '<td valign="top">I like the visual presentation and the colors here. not as sharp as I would like to see but works very well. how did you light this? I tried working with citrus fruit previously and didn''t get as nice results as you have created.</td>', 'I like the visual presentation and the colors here. not as sharp as I would like to see but works very well. how did you light this? I tried working with citrus fruit previously and didn''t get as nice results as you have created.', '2003-09-22 10:30:01.000000', NULL, 1),
(425816, 38734, 6624, '<td valign="top">this is lovely light on the acorns, the white circle distracts badly from the composition as a whole</td>', 'this is lovely light on the acorns, the white circle distracts badly from the composition as a whole', '2003-09-22 10:31:06.000000', NULL, 1),
(425817, 38856, 92, '<td valign="top">This is really nice. I love the leaf only in it''s beautiful color against the b/w. That adds a nice contrast. The water flow is perfect and not too soft. 9</td>', 'This is really nice. I love the leaf only in it''s beautiful color against the b/w. That adds a nice contrast. The water flow is perfect and not too soft. 9', '2003-09-22 10:31:12.000000', NULL, 1),
(425818, 38962, 8624, '<td valign="top">I would like to have seen greater DOF and better tonal range. I usually like shallow DOF shots, but the snake has interesting textures and the fingers would have provided a better sense of scale had they been more in focus.</td>', 'I would like to have seen greater DOF and better tonal range. I usually like shallow DOF shots, but the snake has interesting textures and the fingers would have provided a better sense of scale had they been more in focus.', '2003-09-22 10:31:49.000000', NULL, 1),
