(425964, 38005, 6624, '<td valign="top">the hole at the boittom is so disracting I can''t get by it to the excellence of the textures and color of the rest</td>', 'the hole at the boittom is so disracting I can''t get by it to the excellence of the textures and color of the rest', '2003-09-22 12:13:18.000000', NULL, 1),
(425968, 38283, 656, '<td valign="top">wing tears and general ''drappyness'' show that its a dead bug on a coin - but still a very sharp shot and good detail.  Seems quite noisy though.</td>', 'wing tears and general ''drappyness'' show that its a dead bug on a coin - but still a very sharp shot and good detail.  Seems quite noisy though.', '2003-09-22 12:20:40.000000', NULL, 1),
(425969, 38665, 656, '<td valign="top">overall dark but excellent none the less.  Shame the mouth parts are cropped as I think they would have added a lot to the impact of the shot.</td>', 'overall dark but excellent none the less.  Shame the mouth parts are cropped as I think they would have added a lot to the impact of the shot.', '2003-09-22 12:22:39.000000', NULL, 1),
(425970, 38677, 656, '<td valign="top">Good control of DoF makes this very effective.</td>', 'Good control of DoF makes this very effective.', '2003-09-22 12:23:15.000000', NULL, 1),
(425972, 38982, 656, '<td valign="top">good imagination - well put together.  The slightly off white/ orangy background doesn''t add a whole lot though.  A bit more light from the front could have helped too.</td>', 'good imagination - well put together.  The slightly off white/ orangy background doesn''t add a whole lot though.  A bit more light from the front could have helped too.', '2003-09-22 12:24:06.000000', NULL, 1),
(425973, 38903, 2567, '<td valign="top">This is one of my favorite flowers.  Focus and colors good.  Good luck.</td>', 'This is one of my favorite flowers.  Focus and colors good.  Good luck.', '2003-09-22 12:26:48.000000', NULL, 1),
(425975, 38955, 2567, '<td valign="top">Black and white does very well for this shot.  Good composition and clarity.  Nice job.</td>', 'Black and white does very well for this shot.  Good composition and clarity.  Nice job.', '2003-09-22 12:27:50.000000', NULL, 1),
(425977, 38741, 6532, '<td valign="top">Cool fade on the subject.  Good use of space and color.</td>', 'Cool fade on the subject.  Good use of space and color.', '2003-09-22 12:28:10.000000', NULL, 1),
(425980, 38991, 2567, '<td valign="top">Love the color.  Nice shot.  Good luck.</td>', 'Love the color.  Nice shot.  Good luck.', '2003-09-22 12:29:34.000000', NULL, 1),
(425982, 38836, 2567, '<td valign="top">Wonderful composition and color.  Good luck.</td>', 'Wonderful composition and color.  Good luck.', '2003-09-22 12:30:24.000000', NULL, 1),
