(425988, 38939, 9441, '<td valign="top">Wonderfully done....nice pattern, great focus on detail...I like the overall "feel" of this photo</td>', 'Wonderfully done....nice pattern, great focus on detail...I like the overall "feel" of this photo', '2003-09-22 12:33:52.000000', NULL, 1),
(425991, 38384, 6532, '<td valign="top">Lighting in the left middle third makes it difficult to see the details.  Possibly would have considered changing the light source.</td>', 'Lighting in the left middle third makes it difficult to see the details.  Possibly would have considered changing the light source.', '2003-09-22 12:35:30.000000', NULL, 1),
(425992, 38239, 7342, '<td valign="top">What is it?</td>', 'What is it?', '2003-09-22 12:36:17.000000', NULL, 1),
(425994, 38721, 7628, '<td valign="top">lovely colors, detail and texture.  The "dewlap" and front leg aren''t in focus, and destract the eye from the central subject.  They do provide some context  - but  i''d experiment with croppin them out.</td>', 'lovely colors, detail and texture.  The "dewlap" and front leg aren''t in focus, and destract the eye from the central subject.  They do provide some context  - but  i''d experiment with croppin them out.', '2003-09-22 12:38:20.000000', NULL, 1),
(425997, 38897, 6532, '<td valign="top">Seems a bit blurry, out of focus.</td>', 'Seems a bit blurry, out of focus.', '2003-09-22 12:40:06.000000', NULL, 1),
(425998, 38222, 3569, '<td valign="top">Great shot.  Colorsare  nice.</td>', 'Great shot.  Colorsare  nice.', '2003-09-22 12:40:19.000000', NULL, 1),
(425999, 38733, 3569, '<td valign="top">Nice contrasting colors on the Morning Glory.</td>', 'Nice contrasting colors on the Morning Glory.', '2003-09-22 12:41:16.000000', NULL, 1),
(426000, 38341, 7628, '<td valign="top">interesting detail of the root (?) popping out.  the color is rich, but the lighting is too bright, makes the seeds so shiny it is hard to see the texture.  Also the depth of focus is so small, very little of the pic is clear.  I like to see a crop that brings us closer to the root andthe bit of seed thjat is in focus.</td>', 'interesting detail of the root (?) popping out.  the color is rich, but the lighting is too bright, makes the seeds so shiny it is hard to see the texture.  Also the depth of focus is so small, very little of the pic is clear.  I like to see a crop that brings us closer to the root andthe bit of seed thjat is in focus.', '2003-09-22 12:41:25.000000', NULL, 1),
(426001, 38681, 6532, '<td valign="top">Wonderful clarity and simplicity.  Good job.</td>', 'Wonderful clarity and simplicity.  Good job.', '2003-09-22 12:41:37.000000', NULL, 1),
(426002, 38188, 2567, '<td valign="top">Everything looks out of focus to me in this shot.  Interesting idea though.</td>', 'Everything looks out of focus to me in this shot.  Interesting idea though.', '2003-09-22 12:41:40.000000', NULL, 1),
(426003, 38670, 6532, '<td valign="top">Nice.  Definitely up-close!  Good job</td>', 'Nice.  Definitely up-close!  Good job', '2003-09-22 12:42:59.000000', NULL, 1),
(426004, 38955, 3569, '<td valign="top">Wow!!!!  The shades, sharpness and textures.  Great shot in all ways.  Good luck...</td>', 'Wow!!!!  The shades, sharpness and textures.  Great shot in all ways.  Good luck...', '2003-09-22 12:43:11.000000', NULL, 1),
(426005, 38763, 3569, '<td valign="top">The flash/lighting overexposed the diamonds and gold, so details are lost.</td>', 'The flash/lighting overexposed the diamonds and gold, so details are lost.', '2003-09-22 12:44:26.000000', NULL, 1),
