INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(426007, 38878, 6532, '<td valign="top">Nice.</td>', 'Nice.', '2003-09-22 12:45:12.000000', NULL, 1),
(426008, 38281, 7628, '<td valign="top">nice detail on the right hand screw.  I wonder at your choice to have a narrow dof.  the composition of the other screws and nuts is visually interesting, but without focus just detracts from the subject.  An even background filled with nuts, bolts, whatever, out of focus would give a nice back drop to one screw in focus.  Another question - why color, why not b&amp;w?</td>', 'nice detail on the right hand screw.  I wonder at your choice to have a narrow dof.  the composition of the other screws and nuts is visually interesting, but without focus just detracts from the subject.  An even background filled with nuts, bolts, whatever, out of focus would give a nice back drop to one screw in focus.  Another question - why color, why not b&w?', '2003-09-22 12:45:43.000000', NULL, 1),
(426009, 38001, 3569, '<td valign="top">The colors and texture are really nice.  The lichens colors right on.  Nice job.</td>', 'The colors and texture are really nice.  The lichens colors right on.  Nice job.', '2003-09-22 12:46:26.000000', NULL, 1),
(426010, 38409, 2567, '<td valign="top">Nice shot but please get rid of the time, detracts from the pic.</td>', 'Nice shot but please get rid of the time, detracts from the pic.', '2003-09-22 12:47:09.000000', NULL, 1),
(426011, 38976, 7628, '<td valign="top">i like the brown color and bark texture against tje smooth black.  Wish the whole subject were in focus, maybe crop in to give more cohesion to the picture.</td>', 'i like the brown color and bark texture against tje smooth black.  Wish the whole subject were in focus, maybe crop in to give more cohesion to the picture.', '2003-09-22 12:47:32.000000', NULL, 1),
(426012, 38406, 3569, '<td valign="top">IMO-The frame doen''t help this shot at all.  The photo is nice though.</td>', 'IMO-The frame doen''t help this shot at all.  The photo is nice though.', '2003-09-22 12:47:33.000000', NULL, 1),
(426013, 38899, 2567, '<td valign="top">Sorry but this looks entirely out of focus.</td>', 'Sorry but this looks entirely out of focus.', '2003-09-22 12:47:55.000000', NULL, 1),
(426014, 38804, 3569, '<td valign="top">Great shot in all ways, especially the reddish-brown and green contrasts.</td>', 'Great shot in all ways, especially the reddish-brown and green contrasts.', '2003-09-22 12:48:37.000000', NULL, 1),
(426015, 38626, 3569, '<td valign="top">The blues work well with this shot.  Good job.</td>', 'The blues work well with this shot.  Good job.', '2003-09-22 12:49:31.000000', NULL, 1),
(426016, 38870, 6668, '<td valign="top">The shadow on the filter is distracting, it looks almost like the filter is split in two.</td>', 'The shadow on the filter is distracting, it looks almost like the filter is split in two.', '2003-09-22 12:49:56.000000', NULL, 1),
(426017, 38792, 6532, '<td valign="top">Would have preferred this in a portrait layout versus this landscape.  Great contrast and simplicity.  Good job.</td>', 'Would have preferred this in a portrait layout versus this landscape.  Great contrast and simplicity.  Good job.', '2003-09-22 12:50:02.000000', NULL, 1),
(426018, 38956, 3569, '<td valign="top">Appears to be a bit grainy.  Colors are nice.</td>', 'Appears to be a bit grainy.  Colors are nice.', '2003-09-22 12:50:28.000000', NULL, 1),
(426019, 38881, 7628, '<td valign="top">Very nice I like the balance of having two faces - one in focus, and one, like an echo, suggested in the background,  The difference in their expressions is interesting too - gives real feeling to the picture,  Depth of Focus on the foreground figure is narrow - wish all of the face was sharp.  I might have cropped on the right to loose the white blotch at the top.</td>', 'Very nice I like the balance of having two faces - one in focus, and one, like an echo, suggested in the background,  The difference in their expressions is interesting too - gives real feeling to the picture,  Depth of Focus on the foreground figure is narrow - wish all of the face was sharp.  I might have cropped on the right to loose the white blotch at the top.', '2003-09-22 12:51:09.000000', NULL, 1),
(426021, 38188, 6532, '<td valign="top">Seems grainy.</td>', 'Seems grainy.', '2003-09-22 12:52:00.000000', NULL, 1),
(426022, 38005, 3569, '<td valign="top">This is great.  The pores of the animals really show up nicely without overexposure.  You did well....</td>', 'This is great.  The pores of the animals really show up nicely without overexposure.  You did well....', '2003-09-22 12:52:27.000000', NULL, 1),
(426023, 38425, 7628, '<td valign="top">Lots of meaning in such a small spot - the light through the blinds, the time on the watch.  Nice focus, texture in the hand - the skin the mails.  Very neat, well done.</td>', 'Lots of meaning in such a small spot - the light through the blinds, the time on the watch.  Nice focus, texture in the hand - the skin the mails.  Very neat, well done.', '2003-09-22 12:53:35.000000', NULL, 1),
(426024, 38721, 5475, '<td valign="top">The color and the detail in this shot are wonderful!  I have a Tokay Gecko, which is a turquiose and orange color.  I wanted to shoot him for this challenge, but didn''t have the time.  Your lighting is prfect for this shot...  The only thing I would change, if anything at all, would be a solid background.  That is not always possible for a shot like thei though, due to environment not being set up for the shot.  Well done!<br/>JD Anderson</td>', 'The color and the detail in this shot are wonderful!  I have a Tokay Gecko, which is a turquiose and orange color.  I wanted to shoot him for this challenge, but didn''t have the time.  Your lighting is prfect for this shot...  The only thing I would change, if anything at all, would be a solid background.  That is not always possible for a shot like thei though, due to environment not being set up for the shot.  Well done!JD Anderson', '2003-09-22 12:53:44.000000', NULL, 1),
(426025, 38088, 2567, '<td valign="top">Nice shot.  One of my favorites this challenge.</td>', 'Nice shot.  One of my favorites this challenge.', '2003-09-22 12:53:57.000000', NULL, 1),
(426026, 38963, 7342, '<td valign="top">The epitomy of MACRO!</td>', 'The epitomy of MACRO!', '2003-09-22 12:55:07.000000', NULL, 1),
(426027, 38875, 3569, '<td valign="top">Great shot of the flower parts and contrasts right on.  Nice shot.</td>', 'Great shot of the flower parts and contrasts right on.  Nice shot.', '2003-09-22 12:55:30.000000', NULL, 1),
(426030, 38853, 7628, '<td valign="top">Surreal.  I can see the obvious center to the flower, pretty sharp and detailed.  The sudden shift to extremely blurry petals is jarring.  Although my eyes know what it is, they can''t pull it all together.  Perhaps better lighting - less light, from multiple sources/levels - would illuminate the details of the cetner better, and make a more gentle transition to the petals.</td>', 'Surreal.  I can see the obvious center to the flower, pretty sharp and detailed.  The sudden shift to extremely blurry petals is jarring.  Although my eyes know what it is, they can''t pull it all together.  Perhaps better lighting - less light, from multiple sources/levels - would illuminate the details of the cetner better, and make a more gentle transition to the petals.', '2003-09-22 12:56:50.000000', NULL, 1),
(426031, 38260, 3569, '<td valign="top">Macro or telephoto.... Nice shot of the cow elk though</td>', 'Macro or telephoto.... Nice shot of the cow elk though', '2003-09-22 12:57:54.000000', NULL, 1),
(426033, 38060, 7628, '<td valign="top">Stanger in a strange land - Space Mushroom!  Interesting - the curves of the glass (vase?) and the organic fungus contrast nicely with the grid in the background. Wish the glass and fungus were entirely sharp so they''d "pop" out of the background better.</td>', 'Stanger in a strange land - Space Mushroom!  Interesting - the curves of the glass (vase?) and the organic fungus contrast nicely with the grid in the background. Wish the glass and fungus were entirely sharp so they''d "pop" out of the background better.', '2003-09-22 12:59:23.000000', NULL, 1),
(426034, 38996, 656, '<td valign="top">A great subject but technically could maybe be a bit brighter and more exposed ?</td>', 'A great subject but technically could maybe be a bit brighter and more exposed ?', '2003-09-22 13:00:26.000000', NULL, 1),
(426036, 38914, 2567, '<td valign="top">Terrific composition.  Very refreshing idea.  Good color.  Good luck with the challenge.</td>', 'Terrific composition.  Very refreshing idea.  Good color.  Good luck with the challenge.', '2003-09-22 13:00:49.000000', NULL, 1),
(426037, 38836, 6668, '<td valign="top">to dark to really be able to tell what it is without the title.</td>', 'to dark to really be able to tell what it is without the title.', '2003-09-22 13:01:09.000000', NULL, 1),
(426039, 38872, 7628, '<td valign="top">I like the fuzziness of the bee, the blurr of the hard-working wings.  It must have been hard to get as the bee wiggled the flower around.  Ideally I''d love the flower, the all of the bee to be sharp - stoppped in motion.  I''d also crop in closer to the bee and flower - from the top and the right.</td>', 'I like the fuzziness of the bee, the blurr of the hard-working wings.  It must have been hard to get as the bee wiggled the flower around.  Ideally I''d love the flower, the all of the bee to be sharp - stoppped in motion.  I''d also crop in closer to the bee and flower - from the top and the right.', '2003-09-22 13:01:29.000000', NULL, 1),
(426040, 38474, 3569, '<td valign="top">Great take on the challenge.  The seeds work well with the rest of the shot and add a demension that makes the shot.  Good job.</td>', 'Great take on the challenge.  The seeds work well with the rest of the shot and add a demension that makes the shot.  Good job.', '2003-09-22 13:01:39.000000', NULL, 1),
(426042, 38477, 6668, '<td valign="top">cropped a little too close at the top, I like the black and white, but it just really isn''t an interesting shot to look at in my opinion anyway.</td>', 'cropped a little too close at the top, I like the black and white, but it just really isn''t an interesting shot to look at in my opinion anyway.', '2003-09-22 13:02:55.000000', NULL, 1),
(426046, 38734, 7628, '<td valign="top">Nice subject and composition - the line of the branch leaning up to the corner, the other corner framed with leaves.  I can''t shake the feeling this is upside down - I guess my eyes feel the acorns should hang (even in they really don''t)  Wish at least the front three acorns were sharper.</td>', 'Nice subject and composition - the line of the branch leaning up to the corner, the other corner framed with leaves.  I can''t shake the feeling this is upside down - I guess my eyes feel the acorns should hang (even in they really don''t)  Wish at least the front three acorns were sharper.', '2003-09-22 13:03:46.000000', NULL, 1),
(426047, 38476, 3569, '<td valign="top">Now this is a macro.  What a great shot.  He''s smiling and you will be with the ribbon this will get.  Great shot.</td>', 'Now this is a macro.  What a great shot.  He''s smiling and you will be with the ribbon this will get.  Great shot.', '2003-09-22 13:04:18.000000', NULL, 1),
(426049, 38982, 7342, '<td valign="top">Good humor, good color, good background, great idea!  Presented quite well.</td>', 'Good humor, good color, good background, great idea!  Presented quite well.', '2003-09-22 13:06:31.000000', NULL, 1),
(426050, 38681, 2125, '<td valign="top">excellent capture!! the bug is soo crisp and bug junior is so ...lunch! lol 10</td>', 'excellent capture!! the bug is soo crisp and bug junior is so ...lunch! lol 10', '2003-09-22 13:06:38.000000', NULL, 1),
(426051, 38812, 3569, '<td valign="top">I like this shot.  But I would have given it a higher score if you had cropped approx. 1/3 higher where the ants are more subject matter.</td>', 'I like this shot.  But I would have given it a higher score if you had cropped approx. 1/3 higher where the ants are more subject matter.', '2003-09-22 13:07:01.000000', NULL, 1),
(426053, 38955, 6668, '<td valign="top">Nice capture, at first I was thinking that this picture would look better in color, but the more I look at it the more I like the black and white, I also like the border you''ve added.</td>', 'Nice capture, at first I was thinking that this picture would look better in color, but the more I look at it the more I like the black and white, I also like the border you''ve added.', '2003-09-22 13:07:20.000000', NULL, 1),
(426055, 38060, 2125, '<td valign="top">wow!! that is a killer shot !!! i love it cause you ''figure it out'' if you know what I mean i bet you get at least 1st place if not 1st second and third... maybe try to cut the right half off see what it looks like... just the extra space on the right  would love to know the setup for this shot 10+</td>', 'wow!! that is a killer shot !!! i love it cause you ''figure it out'' if you know what I mean i bet you get at least 1st place if not 1st second and third... maybe try to cut the right half off see what it looks like... just the extra space on the right  would love to know the setup for this shot 10+', '2003-09-22 13:08:33.000000', NULL, 1),
(426056, 39006, 3569, '<td valign="top">Out of old marbles, interesting.  I like the brooch and idea, but the shot is somewhat bland.</td>', 'Out of old marbles, interesting.  I like the brooch and idea, but the shot is somewhat bland.', '2003-09-22 13:08:51.000000', NULL, 1),
(426058, 38895, 2125, '<td valign="top">you even have catch lights on the doll''s eyes very creative 9</td>', 'you even have catch lights on the doll''s eyes very creative 9', '2003-09-22 13:09:22.000000', NULL, 1),
(426059, 38763, 9441, '<td valign="top">too unclear, doesn''t show the detail crisp enough</td>', 'too unclear, doesn''t show the detail crisp enough', '2003-09-22 13:09:49.000000', NULL, 1),
(426060, 38476, 2125, '<td valign="top">i am so glad our eyes aren''t macro..this is downright scary! nice shot 10 +</td>', 'i am so glad our eyes aren''t macro..this is downright scary! nice shot 10 +', '2003-09-22 13:09:56.000000', NULL, 1),
(426061, 37996, 656, '<td valign="top">reminds me of an old film  - very soft, great light, charming.</td>', 'reminds me of an old film  - very soft, great light, charming.', '2003-09-22 13:10:03.000000', NULL, 1),
