(426361, 39011, 6668, '<td valign="top">I don''t particularily care for the background or the uneven white border.</td>', 'I don''t particularily care for the background or the uneven white border.', '2003-09-22 16:59:16.000000', NULL, 1),
(426363, 38228, 6668, '<td valign="top">what is that that the water is splashing off of? I like the clearness of the water, but the top portion is distracting not knowing what it is.</td>', 'what is that that the water is splashing off of? I like the clearness of the water, but the top portion is distracting not knowing what it is.', '2003-09-22 17:00:50.000000', NULL, 1),
