(426371, 38660, 327, '<td valign="top">Yikes, would had to meet this in a dark alley!! Creepy looking guy...!</td>', 'Yikes, would had to meet this in a dark alley!! Creepy looking guy...!', '2003-09-22 17:04:37.000000', NULL, 1),
(426372, 38875, 327, '<td valign="top">Wonderful composition, just a wee bit dark, but I love the shot, the color is awesome.</td>', 'Wonderful composition, just a wee bit dark, but I love the shot, the color is awesome.', '2003-09-22 17:05:29.000000', NULL, 1),
