INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(426378, 38741, 327, '<td valign="top">Very neat shot.  Love the dof and the color. Fine work.</td>', 'Very neat shot.  Love the dof and the color. Fine work.', '2003-09-22 17:08:27.000000', NULL, 1),
(426379, 38774, 327, '<td valign="top">Different plant, almost looks like fingers with gloves on. Neat shot.</td>', 'Different plant, almost looks like fingers with gloves on. Neat shot.', '2003-09-22 17:09:06.000000', NULL, 1),
(426380, 38146, 6668, '<td valign="top">too much sun glare on his face, maybe if this photo was taken at a different time of day that could have been prevented.</td>', 'too much sun glare on his face, maybe if this photo was taken at a different time of day that could have been prevented.', '2003-09-22 17:09:46.000000', NULL, 1),
(426382, 38005, 327, '<td valign="top">Beautiful view of so delicate shell.</td>', 'Beautiful view of so delicate shell.', '2003-09-22 17:10:19.000000', NULL, 1),
(426384, 38351, 327, '<td valign="top">Kool perspective view of these two points. Very different and fun. Nice going.</td>', 'Kool perspective view of these two points. Very different and fun. Nice going.', '2003-09-22 17:11:05.000000', NULL, 1),
(426386, 38962, 327, '<td valign="top">lol  -love this view of a ?snake. He even has a name? Wow such big eyes.</td>', 'lol  -love this view of a ?snake. He even has a name? Wow such big eyes.', '2003-09-22 17:12:15.000000', NULL, 1),
(426389, 38963, 327, '<td valign="top">Fantastic shot, fantastic. Wow this is up close and in your face....errrrrh his face. :)</td>', 'Fantastic shot, fantastic. Wow this is up close and in your face....errrrrh his face. :)', '2003-09-22 17:13:02.000000', NULL, 1),
(426390, 38001, 327, '<td valign="top">Very good shot, you have a good eye. What a fantastic find. Amazing colors and texture.</td>', 'Very good shot, you have a good eye. What a fantastic find. Amazing colors and texture.', '2003-09-22 17:13:58.000000', NULL, 1),
(426392, 39001, 6668, '<td valign="top">LOL, Love her hair!</td>', 'LOL, Love her hair!', '2003-09-22 17:15:12.000000', NULL, 1),
(426393, 38813, 327, '<td valign="top">Nice color and view of lace wings. Good work.</td>', 'Nice color and view of lace wings. Good work.', '2003-09-22 17:15:17.000000', NULL, 1),
(426394, 38300, 6624, '<td valign="top">the concept is interesting but the dust gets a bit lost in the light spots</td>', 'the concept is interesting but the dust gets a bit lost in the light spots', '2003-09-22 17:15:29.000000', NULL, 1),
(426396, 38192, 6668, '<td valign="top">The glare on the top of the rock is a little distracting, otherwise nice shot, I also like the black and gold border you used on this.</td>', 'The glare on the top of the rock is a little distracting, otherwise nice shot, I also like the black and gold border you used on this.', '2003-09-22 17:17:55.000000', NULL, 1),
(426399, 38999, 6668, '<td valign="top">Nice colors and detail on his body.</td>', 'Nice colors and detail on his body.', '2003-09-22 17:19:49.000000', NULL, 1),
(426401, 38741, 6668, '<td valign="top">cool photo, almost looks as if it is speeding towards us.</td>', 'cool photo, almost looks as if it is speeding towards us.', '2003-09-22 17:21:16.000000', NULL, 1),
(426410, 38247, 9131, '<td valign="top">i think the pink background detracts from the flower a bit.  it ouwld be better is the colors weren''t so similar.  nice shot otherwise.</td>', 'i think the pink background detracts from the flower a bit.  it ouwld be better is the colors weren''t so similar.  nice shot otherwise.', '2003-09-22 17:33:33.000000', NULL, 1),
(426412, 38665, 9131, '<td valign="top">wow! very cool shot! i love the eyes, that you can see the dots.</td>', 'wow! very cool shot! i love the eyes, that you can see the dots.', '2003-09-22 17:34:32.000000', NULL, 1),
(426413, 38428, 9131, '<td valign="top">funny, this is very similar to the plant that i photographed for this challenge! wouldn''t this be better horizontal?</td>', 'funny, this is very similar to the plant that i photographed for this challenge! wouldn''t this be better horizontal?', '2003-09-22 17:35:58.000000', NULL, 1),
(426414, 38856, 9131, '<td valign="top">very nice.  great contrast between leaf and background. the running water just makes it even better. this could be a winner!</td>', 'very nice.  great contrast between leaf and background. the running water just makes it even better. this could be a winner!', '2003-09-22 17:38:47.000000', NULL, 1),
(426415, 38721, 6624, '<td valign="top">very fine and noble iguana...textures are very nice and although I might have thought a crop on the lower part, right to the sharper green scales (?) I like what you have done as well</td>', 'very fine and noble iguana...textures are very nice and although I might have thought a crop on the lower part, right to the sharper green scales (?) I like what you have done as well', '2003-09-22 17:38:56.000000', NULL, 1),
(426416, 38620, 9131, '<td valign="top">this could be a spectacular shot if focus was just a little more crisp.</td>', 'this could be a spectacular shot if focus was just a little more crisp.', '2003-09-22 17:40:32.000000', NULL, 1),
(426419, 38975, 6624, '<td valign="top">the color balance and textures are very satisfying, and the eye is fascinating</td>', 'the color balance and textures are very satisfying, and the eye is fascinating', '2003-09-22 17:42:47.000000', NULL, 1),
(426420, 38449, 9131, '<td valign="top">a great expression! good focus, especially for a moving subject!  i know how difficult it can be to take picture of cats!  they do what they want...</td>', 'a great expression! good focus, especially for a moving subject!  i know how difficult it can be to take picture of cats!  they do what they want...', '2003-09-22 17:43:55.000000', NULL, 1),
(426425, 38010, 9131, '<td valign="top">very cool contrasts &amp; depth &amp; lighting.</td>', 'very cool contrasts & depth & lighting.', '2003-09-22 17:52:33.000000', NULL, 1),
(426426, 38408, 10084, '<td valign="top">Very interesting composition. Love the beautiful shadow of the screw. Would like to see less noise.  It''s a bit distracting. Less noise would give more darkness in the shadow and give it even more impact.</td>', 'Very interesting composition. Love the beautiful shadow of the screw. Would like to see less noise.  It''s a bit distracting. Less noise would give more darkness in the shadow and give it even more impact.', '2003-09-22 17:53:01.000000', NULL, 1),
(426432, 38919, 10084, '<td valign="top">Absolutely beautiful lighting. The shadows and the lighting really make the first subject pop out of the picture. It gives you a great sense of tec=xture in the mask. The depth of field really separates each mask.</td>', 'Absolutely beautiful lighting. The shadows and the lighting really make the first subject pop out of the picture. It gives you a great sense of tec=xture in the mask. The depth of field really separates each mask.', '2003-09-22 17:57:14.000000', NULL, 1),
(426433, 38757, 7628, '<td valign="top">Interesting subject, cool shaddow.  The background looks flat - are they real poppies or pictures of poppies?  Focus seems a bit soft.</td>', 'Interesting subject, cool shaddow.  The background looks flat - are they real poppies or pictures of poppies?  Focus seems a bit soft.', '2003-09-22 17:58:10.000000', NULL, 1),
(426442, 39009, 7628, '<td valign="top">Interesting composition - half a bug, focuses on the angles.  Focus is soft - wish it were really sharp ''cause I can see all those great hairs on it''s leg.  The pic is very bright, wish there was more contrast - a darker background</td>', 'Interesting composition - half a bug, focuses on the angles.  Focus is soft - wish it were really sharp ''cause I can see all those great hairs on it''s leg.  The pic is very bright, wish there was more contrast - a darker background', '2003-09-22 18:08:53.000000', NULL, 1),
(426444, 38476, 7628, '<td valign="top">Nice title. What a "mask" it stands out even more in contrast to the soft fuzz at the neck.I like the depth of the colors, and the detailed texture in those eyes.</td>', 'Nice title. What a "mask" it stands out even more in contrast to the soft fuzz at the neck.I like the depth of the colors, and the detailed texture in those eyes.', '2003-09-22 18:10:46.000000', NULL, 1),
(426445, 38678, 7628, '<td valign="top">Lovely image/composition.  The blooms seem to float.</td>', 'Lovely image/composition.  The blooms seem to float.', '2003-09-22 18:11:41.000000', NULL, 1),
(426448, 38257, 7628, '<td valign="top">Great colors.  I like the water drops.  Wish the petal to the right wasn''t cropped off.    Focus seems a bit soft.</td>', 'Great colors.  I like the water drops.  Wish the petal to the right wasn''t cropped off.    Focus seems a bit soft.', '2003-09-22 18:14:21.000000', NULL, 1),
(426450, 38848, 7628, '<td valign="top">Nive color/texture contrasts.  The flower is the focus, but it is getting a bit lost is that busy background.  Crop down a bit.</td>', 'Nive color/texture contrasts.  The flower is the focus, but it is getting a bit lost is that busy background.  Crop down a bit.', '2003-09-22 18:15:50.000000', NULL, 1),
(426451, 38222, 7628, '<td valign="top">The composition really enhances the effect of the crab peering out at the world timidly.Nice colors, lighting good - I like the way the eyes are frames againtst the darkness under the shell.  Focus seems a bit soft, but I find I''m saying that lot - maybe I need new glasses.  Do wish the frame didn''t disappear into the background on the left.  Darker color?</td>', 'The composition really enhances the effect of the crab peering out at the world timidly.Nice colors, lighting good - I like the way the eyes are frames againtst the darkness under the shell.  Focus seems a bit soft, but I find I''m saying that lot - maybe I need new glasses.  Do wish the frame didn''t disappear into the background on the left.  Darker color?', '2003-09-22 18:18:48.000000', NULL, 1),
(426452, 38278, 7628, '<td valign="top">Simple, elegant.  The texture of the eggshell and the whisk contrast well.  The lighting is good,  great shadows.  A print of this would look great in the kitchen, or at a bakery.  Larger DOF would be even better - everything tack sharp.</td>', 'Simple, elegant.  The texture of the eggshell and the whisk contrast well.  The lighting is good,  great shadows.  A print of this would look great in the kitchen, or at a bakery.  Larger DOF would be even better - everything tack sharp.', '2003-09-22 18:21:16.000000', NULL, 1),
(426453, 38966, 7628, '<td valign="top">Here I like the blurr.  Reminds me of how things look when you have a BAD headache.</td>', 'Here I like the blurr.  Reminds me of how things look when you have a BAD headache.', '2003-09-22 18:22:25.000000', NULL, 1),
(426454, 38409, 11506, '<td valign="top">This is a really great photo if you had just lost the time stamp in the bottom corner.</td>', 'This is a really great photo if you had just lost the time stamp in the bottom corner.', '2003-09-22 18:23:13.000000', NULL, 1),
(426455, 38721, 327, '<td valign="top">Wonderful and engaging. The color is so nice. Excellent shot.</td>', 'Wonderful and engaging. The color is so nice. Excellent shot.', '2003-09-22 18:23:29.000000', NULL, 1),
(426456, 38518, 7628, '<td valign="top">Shimering spines.  I like how bright they are.  The pic is quite grainy, detracts from the sharpness of the subject.  Composition is busy - my eye isn''t sure where to look.</td>', 'Shimering spines.  I like how bright they are.  The pic is quite grainy, detracts from the sharpness of the subject.  Composition is busy - my eye isn''t sure where to look.', '2003-09-22 18:24:31.000000', NULL, 1),
(426457, 38474, 327, '<td valign="top">I see what you were trying to achieve here..it''s a great classic idea. Nice going. I do think a bit of levels adjustment would been an improvement.</td>', 'I see what you were trying to achieve here..it''s a great classic idea. Nice going. I do think a bit of levels adjustment would been an improvement.', '2003-09-22 18:24:43.000000', NULL, 1),
(426458, 38592, 327, '<td valign="top">Very clever idea. Neat colors.</td>', 'Very clever idea. Neat colors.', '2003-09-22 18:25:37.000000', NULL, 1),
(426459, 38247, 327, '<td valign="top">Lovely colors and fantastic perspective view.</td>', 'Lovely colors and fantastic perspective view.', '2003-09-22 18:26:11.000000', NULL, 1),
(426460, 38871, 7628, '<td valign="top">I like the light on her eyes - draws the viewer''s eyes in.  having the mouth in the shadow is fine, but i wish i could see it just a little better - a bit more light.</td>', 'I like the light on her eyes - draws the viewer''s eyes in.  having the mouth in the shadow is fine, but i wish i could see it just a little better - a bit more light.', '2003-09-22 18:26:15.000000', NULL, 1),
(426461, 38935, 327, '<td valign="top">Not a bad shot and a good idea. I''m not too crazy about the lighting. Nice b&amp;w.</td>', 'Not a bad shot and a good idea. I''m not too crazy about the lighting. Nice b&w.', '2003-09-22 18:26:55.000000', NULL, 1),
(426462, 38292, 7628, '<td valign="top">Nice detail, I like the bit of color in an almost colorless subject.  The texture of the jack in good, the background texture balances it without distracting.  Wish for a greater DOF.</td>', 'Nice detail, I like the bit of color in an almost colorless subject.  The texture of the jack in good, the background texture balances it without distracting.  Wish for a greater DOF.', '2003-09-22 18:28:01.000000', NULL, 1),
(426463, 38949, 327, '<td valign="top">Jewelery is difficult to shoot. The light is tricky. You made a good try. I believe the shine on the material is a detriment to the over all shot.</td>', 'Jewelery is difficult to shoot. The light is tricky. You made a good try. I believe the shine on the material is a detriment to the over all shot.', '2003-09-22 18:28:01.000000', NULL, 1),
(426465, 38754, 7628, '<td valign="top">Interesting contrasts.  Hard to pick out what things are or see detail in them.</td>', 'Interesting contrasts.  Hard to pick out what things are or see detail in them.', '2003-09-22 18:28:56.000000', NULL, 1),
(426466, 37996, 327, '<td valign="top">Looks mystic and heavenly. Lovely shot, lovely work ....congratsulations.</td>', 'Looks mystic and heavenly. Lovely shot, lovely work ....congratsulations.', '2003-09-22 18:29:04.000000', NULL, 1),
