(426660, 38739, 6668, '<td valign="top">The matches don''t fit in this photo to me, I think it would be nicer with just the watch.</td>', 'The matches don''t fit in this photo to me, I think it would be nicer with just the watch.', '2003-09-22 21:00:55.000000', NULL, 1),
(426661, 38859, 10084, '<td valign="top">Beautiful colors.  Not too much details, but this helps the colors really blend together and gives a great composition. Feels almost like a painting.</td>', 'Beautiful colors.  Not too much details, but this helps the colors really blend together and gives a great composition. Feels almost like a painting.', '2003-09-22 21:01:58.000000', NULL, 1),
