(426667, 38962, 6668, '<td valign="top">would have been better if the picture could have been taken without the snake being held in the persons hand.</td>', 'would have been better if the picture could have been taken without the snake being held in the persons hand.', '2003-09-22 21:04:55.000000', NULL, 1),
(426670, 38366, 6668, '<td valign="top">Beautiful contrast of colors.</td>', 'Beautiful contrast of colors.', '2003-09-22 21:06:25.000000', NULL, 1),
(426672, 38399, 6668, '<td valign="top">cute idea</td>', 'cute idea', '2003-09-22 21:07:43.000000', NULL, 1),
(426674, 38670, 772, '<td valign="top">Beautiful work... I love the softness of this photo. I saw a similar composition recently done with a stargazer lily that was completely backlit.  This flower potentially has the same opportunity.. I think it takes a very bright source light to pull it off :)  Excellent photo :) = 10</td>', 'Beautiful work... I love the softness of this photo. I saw a similar composition recently done with a stargazer lily that was completely backlit.  This flower potentially has the same opportunity.. I think it takes a very bright source light to pull it off :)  Excellent photo :) = 10', '2003-09-22 21:09:02.000000', NULL, 1),
(426676, 38010, 6668, '<td valign="top">I like the shadow.....curious how this was done within rules.</td>', 'I like the shadow.....curious how this was done within rules.', '2003-09-22 21:11:56.000000', NULL, 1),
