(426764, 38853, 2752, '<td valign="top">This is a lovely abstract approach..well composed .  The focus on the flower centeris well placed and gives it a "wow" for me (10)</td>', 'This is a lovely abstract approach..well composed .  The focus on the flower centeris well placed and gives it a "wow" for me (10)', '2003-09-22 22:52:56.000000', NULL, 1),
(426766, 38963, 11769, '<td valign="top">With those eyes I don''t doubt it! How many compound lenses do these guys have :) 10? No, thats what I scored this shot!</td>', 'With those eyes I don''t doubt it! How many compound lenses do these guys have :) 10? No, thats what I scored this shot!', '2003-09-22 22:54:45.000000', NULL, 1),
(426767, 38724, 10084, '<td valign="top">Beautiful action shot. The lighting really works in this picture. The black background really makes the dominoes pop out of the image. The blurring is absolutely beautiful.</td>', 'Beautiful action shot. The lighting really works in this picture. The black background really makes the dominoes pop out of the image. The blurring is absolutely beautiful.', '2003-09-22 22:55:40.000000', NULL, 1),
