(426771, 38188, 10084, '<td valign="top">A sharper picture would give more interest to the photo. The bright colors help to make the shot pop out of the image.</td>', 'A sharper picture would give more interest to the photo. The bright colors help to make the shot pop out of the image.', '2003-09-22 22:57:42.000000', NULL, 1),
(426775, 38741, 2752, '<td valign="top">I like the fading lighter..compositon is very good and the colors add to the overall feeling of the lighter being engulfed by "fog" (7)</td>', 'I like the fading lighter..compositon is very good and the colors add to the overall feeling of the lighter being engulfed by "fog" (7)', '2003-09-22 23:02:15.000000', NULL, 1),
