INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(426799, 38451, 8696, '<td valign="top">good for next challenge</td>', 'good for next challenge', '2003-09-22 23:27:57.000000', NULL, 1),
(426801, 38670, 11800, '<td valign="top">I''m really thinking this was wonderful.  The only thing is the lightness of the sepal(?).  Really yummy color and focus is perfect.</td>', 'I''m really thinking this was wonderful.  The only thing is the lightness of the sepal(?).  Really yummy color and focus is perfect.', '2003-09-22 23:32:14.000000', NULL, 1),
(426804, 38881, 11800, '<td valign="top">Nice tones.  Maybe, if the front one was all in focus, it would have had a stronger impact. At least the eyes and cheeks.</td>', 'Nice tones.  Maybe, if the front one was all in focus, it would have had a stronger impact. At least the eyes and cheeks.', '2003-09-22 23:40:31.000000', NULL, 1),
(426805, 38804, 9385, '<td valign="top">How did you get him to smile? Wonderful detail. definitely a contender. Good luck</td>', 'How did you get him to smile? Wonderful detail. definitely a contender. Good luck', '2003-09-22 23:42:10.000000', NULL, 1),
(426806, 38962, 7690, '<td valign="top">Great photo and beautiful snake!  10</td>', 'Great photo and beautiful snake!  10', '2003-09-22 23:43:52.000000', NULL, 1),
(426808, 38985, 10084, '<td valign="top">Great closeup of a vehicle interior. The lighting and shadows really gives you a sense of texture in the car. I would like the composition more if the complete handle of the gear shift was included. It seems unfinished with the complete button.</td>', 'Great closeup of a vehicle interior. The lighting and shadows really gives you a sense of texture in the car. I would like the composition more if the complete handle of the gear shift was included. It seems unfinished with the complete button.', '2003-09-22 23:47:29.000000', NULL, 1),
(426809, 38967, 11800, '<td valign="top">Much better than the thumbnail would indicate. If the shadows go the other way, there would be more of a border between the mint and white. Or did you want them to blend together? And I know this is really picky, but the wrinkle on the right side keeps drawing my eye over there.</td>', 'Much better than the thumbnail would indicate. If the shadows go the other way, there would be more of a border between the mint and white. Or did you want them to blend together? And I know this is really picky, but the wrinkle on the right side keeps drawing my eye over there.', '2003-09-22 23:47:33.000000', NULL, 1),
(426811, 38298, 10084, '<td valign="top">The lighting really help to make this shot pop out at you. The white face is very vivid and stands out. Beautiful shadows and reflections on the face of the watch keeps your eyes on the photo. Great depth of field.</td>', 'The lighting really help to make this shot pop out at you. The white face is very vivid and stands out. Beautiful shadows and reflections on the face of the watch keeps your eyes on the photo. Great depth of field.', '2003-09-22 23:49:51.000000', NULL, 1),
(426813, 38856, 10084, '<td valign="top">Very vivid colors in the leaf keep your eyes on it. The reflections of shadows and light in the water makes the water seem to flow off the image. Very crisp and sharp picture. Wow. Framing is awesome.</td>', 'Very vivid colors in the leaf keep your eyes on it. The reflections of shadows and light in the water makes the water seem to flow off the image. Very crisp and sharp picture. Wow. Framing is awesome.', '2003-09-22 23:51:56.000000', NULL, 1),
(426816, 38741, 10084, '<td valign="top">Very cool lighter picture. I like how you were able to make the bottom part of the lighter seem to go forever.  The lighting helps to give some beautiful shadows to the lighter. Beautiful shot.</td>', 'Very cool lighter picture. I like how you were able to make the bottom part of the lighter seem to go forever.  The lighting helps to give some beautiful shadows to the lighter. Beautiful shot.', '2003-09-22 23:55:42.000000', NULL, 1),
(426817, 37984, 4210, '<td valign="top">Great contrast and use of negative space. For some reason it looks unlevel to me, but that could just be my eyes playing tricks,</td>', 'Great contrast and use of negative space. For some reason it looks unlevel to me, but that could just be my eyes playing tricks,', '2003-09-22 23:58:48.000000', NULL, 1),
(426819, 38296, 4210, '<td valign="top">Great detail, clarity, and colours!</td>', 'Great detail, clarity, and colours!', '2003-09-23 00:00:31.000000', NULL, 1),
(426820, 38179, 4210, '<td valign="top">Feels cluttered, slightly unfocused</td>', 'Feels cluttered, slightly unfocused', '2003-09-23 00:00:57.000000', NULL, 1),
(426821, 38977, 11022, '<td valign="top">I love this on many levels, most especially the creativity of the image and the title. Pleasing colors, nice focus, thought it could be a bit sharper on some of the pieces -  and very nice composition.  Good work</td>', 'I love this on many levels, most especially the creativity of the image and the title. Pleasing colors, nice focus, thought it could be a bit sharper on some of the pieces -  and very nice composition.  Good work', '2003-09-23 00:01:20.000000', NULL, 1),
(426822, 38914, 11022, '<td valign="top">Perfect!</td>', 'Perfect!', '2003-09-23 00:01:50.000000', NULL, 1),
(426823, 39007, 4210, '<td valign="top">Eh. I don''t like the dof on this one. It''s close up for sure, but I would like everything to be clear and focused.</td>', 'Eh. I don''t like the dof on this one. It''s close up for sure, but I would like everything to be clear and focused.', '2003-09-23 00:02:24.000000', NULL, 1),
(426825, 38592, 4210, '<td valign="top">awww, it''s one of those little soap things! Great colours!</td>', 'awww, it''s one of those little soap things! Great colours!', '2003-09-23 00:03:10.000000', NULL, 1),
(426826, 38741, 11022, '<td valign="top">Excellent image.  I love the diagonal and the color as it fades into infinity.  Very nicely done and a refreshingly different subject.<br/></td>', 'Excellent image.  I love the diagonal and the color as it fades into infinity.  Very nicely done and a refreshingly different subject.', '2003-09-23 00:03:33.000000', NULL, 1),
(426827, 38366, 1280, '<td valign="top">Pretty</td>', 'Pretty', '2003-09-23 00:05:18.000000', NULL, 1),
(426828, 38877, 11800, '<td valign="top">Nice. A little too hot on the right side, but still a good shot.</td>', 'Nice. A little too hot on the right side, but still a good shot.', '2003-09-23 00:05:19.000000', NULL, 1),
(426835, 38366, 11800, '<td valign="top">The colors and focus are good.  Looks rich.</td>', 'The colors and focus are good.  Looks rich.', '2003-09-23 00:12:06.000000', NULL, 1),
