(427150, 38807, 10768, '<td valign="top">It took me a minute to figure out what this was.  I love the flecks of glitter that show up on the polish.  Nice composition, lighting and striking colors.  Good job.</td>', 'It took me a minute to figure out what this was.  I love the flecks of glitter that show up on the polish.  Nice composition, lighting and striking colors.  Good job.', '2003-09-23 12:22:45.000000', NULL, 1),
(427153, 38351, 10848, '<td valign="top">Great shot! Your camera must have a super macro setting this is terrific and your lighting is superb! Great Job!  Take a bow...I am impressed.</td>', 'Great shot! Your camera must have a super macro setting this is terrific and your lighting is superb! Great Job!  Take a bow...I am impressed.', '2003-09-23 12:24:24.000000', NULL, 1),
(427158, 38283, 10848, '<td valign="top">This shot is too good not to comment on...this is outstanding! Wonderful lighting and the detail is superb! The hairs on the flies back are accented perfectly..I am very impressed! This oughta be a winner for sure!</td>', 'This shot is too good not to comment on...this is outstanding! Wonderful lighting and the detail is superb! The hairs on the flies back are accented perfectly..I am very impressed! This oughta be a winner for sure!', '2003-09-23 12:27:28.000000', NULL, 1),
(427161, 38722, 10848, '<td valign="top">This is a gorgeous picture. The lighting is perfect for this shot. The colors are softened by the outstanding lighting. Great job!</td>', 'This is a gorgeous picture. The lighting is perfect for this shot. The colors are softened by the outstanding lighting. Great job!', '2003-09-23 12:29:07.000000', NULL, 1),
(427165, 38296, 10848, '<td valign="top">Outstanding shot! Great vivid colors and the clarity is superb! Love the detail of the bubbles formed in the glass. Great job!!</td>', 'Outstanding shot! Great vivid colors and the clarity is superb! Love the detail of the bubbles formed in the glass. Great job!!', '2003-09-23 12:31:18.000000', NULL, 1),
(427166, 38620, 10848, '<td valign="top">Wondeful capture! The clarity is excellent. And the detail is wonderful great job!</td>', 'Wondeful capture! The clarity is excellent. And the detail is wonderful great job!', '2003-09-23 12:32:46.000000', NULL, 1),
(427167, 38999, 11793, '<td valign="top">i''d like an explanation of this photo</td>', 'i''d like an explanation of this photo', '2003-09-23 12:33:16.000000', NULL, 1),
(427168, 38856, 10848, '<td valign="top">Excellent capture! Clarity is great and the detail is wonderful...good job! The border is not what I would have used IMHO of course. I always get negative comments on my borders....again great job I love it!</td>', 'Excellent capture! Clarity is great and the detail is wonderful...good job! The border is not what I would have used IMHO of course. I always get negative comments on my borders....again great job I love it!', '2003-09-23 12:36:23.000000', NULL, 1),
