(428572, 38972, 4210, '<td valign="top">Kinda neat. Good lighting.</td>', 'Kinda neat. Good lighting.', '2003-09-24 13:28:58.000000', NULL, 1),
(428574, 37996, 4210, '<td valign="top">Umm... okay. I guess it would be a good shot for a wedding, but for me it''s just screams "too much white!" Actually, it would be a very good shot for a wedding. yay you!</td>', 'Umm... okay. I guess it would be a good shot for a wedding, but for me it''s just screams "too much white!" Actually, it would be a very good shot for a wedding. yay you!', '2003-09-24 13:29:57.000000', NULL, 1),
(428576, 38010, 4210, '<td valign="top">Pretty. I don''t like the high contrast of the black and white though. The plant is beautiful.</td>', 'Pretty. I don''t like the high contrast of the black and white though. The plant is beautiful.', '2003-09-24 13:30:53.000000', NULL, 1),
