(428579, 38260, 4210, '<td valign="top">I know the challenge was to get up close and personal, but this photo is just not doing it for me. It had to have been shot from far away with a long lens, and it just doesn''t say "macro" at all.</td>', 'I know the challenge was to get up close and personal, but this photo is just not doing it for me. It had to have been shot from far away with a long lens, and it just doesn''t say "macro" at all.', '2003-09-24 13:32:17.000000', NULL, 1),
(428583, 38725, 4210, '<td valign="top">Too much negative space. Would have made this a tall and narrow photo personally. Good lighting.</td>', 'Too much negative space. Would have made this a tall and narrow photo personally. Good lighting.', '2003-09-24 13:32:58.000000', NULL, 1),
(428584, 38859, 12464, '<td valign="top">Amazing Color!  Do more with different fruit!  It would be an awsome portfolio, I would hang them in my kitchen!</td>', 'Amazing Color!  Do more with different fruit!  It would be an awsome portfolio, I would hang them in my kitchen!', '2003-09-24 13:33:13.000000', NULL, 1),
