(428767, 38278, 11907, '<td valign="top">Very nice, and I love the title!</td>', 'Very nice, and I love the title!', '2003-09-24 14:47:48.000000', NULL, 1),
(428768, 38623, 4210, '<td valign="top">I don''t like the reflection. I don''t like the ball out in front. Keep working with these balls and mess around with lighting and patterns to see if you can find something that is more appealing to the eye.</td>', 'I don''t like the reflection. I don''t like the ball out in front. Keep working with these balls and mess around with lighting and patterns to see if you can find something that is more appealing to the eye.', '2003-09-24 14:47:56.000000', NULL, 1),
