(428799, 39009, 2883, '<td valign="top">The lighting is too bright and the photo is a littletoo soft.</td>', 'The lighting is too bright and the photo is a littletoo soft.', '2003-09-24 15:00:01.000000', NULL, 1),
(428800, 38722, 2883, '<td valign="top">Nice composition, coloring and lighting.</td>', 'Nice composition, coloring and lighting.', '2003-09-24 15:01:07.000000', NULL, 1),
