(428805, 38967, 2883, '<td valign="top">Good composition and coloring. Very simplistic.</td>', 'Good composition and coloring. Very simplistic.', '2003-09-24 15:03:52.000000', NULL, 1),
(428810, 38010, 2883, '<td valign="top">Very sharp. The white space is a little distracting, which may be due to the border.</td>', 'Very sharp. The white space is a little distracting, which may be due to the border.', '2003-09-24 15:05:09.000000', NULL, 1),
(428813, 38261, 2883, '<td valign="top">This probably would have been better in color. Good composition though.</td>', 'This probably would have been better in color. Good composition though.', '2003-09-24 15:06:31.000000', NULL, 1),
