(429973, 38875, 10084, '<td valign="top">Beautiful colors in the shot. The dark background really helps to make the flower pop out of the shot. Great shadows in the leaf.</td>', 'Beautiful colors in the shot. The dark background really helps to make the flower pop out of the shot. Great shadows in the leaf.', '2003-09-25 04:58:54.000000', NULL, 1),
(429974, 38972, 10084, '<td valign="top">Really good lighting . The shadows and reflections in the image is very vivid. I love the tiled textured in the watch face. This would make for a great ad for "Fossil".</td>', 'Really good lighting . The shadows and reflections in the image is very vivid. I love the tiled textured in the watch face. This would make for a great ad for "Fossil".', '2003-09-25 05:01:08.000000', NULL, 1),
