(431788, 38188, 9168, '<td valign="top">Im assuming you have a bad camera judging by the quality of the photo.  As far as the idea it was good.  Should have had a dark color underneath.<br/></td>', 'Im assuming you have a bad camera judging by the quality of the photo.  As far as the idea it was good.  Should have had a dark color underneath.', '2003-09-26 17:28:42.000000', NULL, 1),
(431789, 38005, 3447, '<td valign="top">First rate color, texture, sharp detail and composition.</td>', 'First rate color, texture, sharp detail and composition.', '2003-09-26 17:29:01.000000', NULL, 1),
(431790, 38972, 9168, '<td valign="top">Good one.  Definitely could work as a product shot.</td>', 'Good one.  Definitely could work as a product shot.', '2003-09-26 17:30:18.000000', NULL, 1),
(431791, 37996, 9168, '<td valign="top">Very neat effect.</td>', 'Very neat effect.', '2003-09-26 17:31:14.000000', NULL, 1),
(431794, 38247, 9168, '<td valign="top">Nice shot, nice background.  Im not sure I agree with the crop, but I obviously dont know the particulars.</td>', 'Nice shot, nice background.  Im not sure I agree with the crop, but I obviously dont know the particulars.', '2003-09-26 17:36:00.000000', NULL, 1),
(431795, 38724, 11457, '<td valign="top">Cool! Since by design you have motion blur to the right, I would have focused on the far pieces to the left.</td>', 'Cool! Since by design you have motion blur to the right, I would have focused on the far pieces to the left.', '2003-09-26 17:36:15.000000', NULL, 1),
(431803, 39002, 9168, '<td valign="top">You lost the details in the washed out area.  Its hard to get the correct exposure in the high-speed world of snail photography :)</td>', 'You lost the details in the washed out area.  Its hard to get the correct exposure in the high-speed world of snail photography :)', '2003-09-26 17:41:15.000000', NULL, 1),
(431809, 38971, 9168, '<td valign="top">I had a similar idea with a lemon, lime and an orange.  Unfortunately, I didnt have the time to pull it off.  I like your shot however.</td>', 'I had a similar idea with a lemon, lime and an orange.  Unfortunately, I didnt have the time to pull it off.  I like your shot however.', '2003-09-26 17:44:48.000000', NULL, 1),
(431815, 38868, 9168, '<td valign="top">Neat shot.  I like the crop and lighting.  The bottom of the leaf, so close to the edge, bugs me a little.  Still a great shot.<br/></td>', 'Neat shot.  I like the crop and lighting.  The bottom of the leaf, so close to the edge, bugs me a little.  Still a great shot.', '2003-09-26 17:47:18.000000', NULL, 1),
(431816, 38951, 3447, '<td valign="top">Nice use of colors, composition and light.</td>', 'Nice use of colors, composition and light.', '2003-09-26 17:50:00.000000', NULL, 1),
(431818, 38725, 9168, '<td valign="top">I like the empty space</td>', 'I like the empty space', '2003-09-26 17:51:16.000000', NULL, 1),
