(431823, 38228, 9168, '<td valign="top">Very cool.  I wish it had a better background color.  Something to make the water really stand out.</td>', 'Very cool.  I wish it had a better background color.  Something to make the water really stand out.', '2003-09-26 17:54:42.000000', NULL, 1),
(431825, 38227, 9168, '<td valign="top">Cool.  Could have been sharper though.</td>', 'Cool.  Could have been sharper though.', '2003-09-26 17:56:04.000000', NULL, 1),
