(432478, 38642, 4210, '<td valign="top">Kinda cute, but the lighting leaves much to be desired, the center weighted composition doesn''t create any tension or interest in the photo, and I would like the background better if I couldn''t tell exactly what it was.</td>', 'Kinda cute, but the lighting leaves much to be desired, the center weighted composition doesn''t create any tension or interest in the photo, and I would like the background better if I couldn''t tell exactly what it was.', '2003-09-27 14:30:04.000000', NULL, 1),
(432480, 38902, 4210, '<td valign="top">Heh. Looks very digital. Good composition.</td>', 'Heh. Looks very digital. Good composition.', '2003-09-27 14:30:34.000000', NULL, 1),
(432481, 38628, 4210, '<td valign="top">Interesting composition. Good clarity.</td>', 'Interesting composition. Good clarity.', '2003-09-27 14:31:06.000000', NULL, 1),
(432482, 39003, 4210, '<td valign="top">Interesting composition. Very clear. Nice.</td>', 'Interesting composition. Very clear. Nice.', '2003-09-27 14:31:27.000000', NULL, 1),
(432483, 38804, 4210, '<td valign="top">Good colour, clarity. Composition is alright.</td>', 'Good colour, clarity. Composition is alright.', '2003-09-27 14:31:54.000000', NULL, 1),
(432484, 38914, 4210, '<td valign="top">Nice lighting. Great colour, and use of negative space.</td>', 'Nice lighting. Great colour, and use of negative space.', '2003-09-27 14:32:27.000000', NULL, 1),
(432485, 38038, 4210, '<td valign="top">Good composition, not so great a camera?</td>', 'Good composition, not so great a camera?', '2003-09-27 14:32:59.000000', NULL, 1),
(432487, 38428, 4210, '<td valign="top">Interesting, but I''m not a big fan of the lighting.</td>', 'Interesting, but I''m not a big fan of the lighting.', '2003-09-27 14:33:26.000000', NULL, 1),
(432488, 38878, 4210, '<td valign="top">Good composition. Interesting subject.</td>', 'Good composition. Interesting subject.', '2003-09-27 14:33:51.000000', NULL, 1),
(432489, 38832, 4210, '<td valign="top">Remember to pay attention to the background when you take your shots. You would have been able to avoid the stuff in the upper left corner.</td>', 'Remember to pay attention to the background when you take your shots. You would have been able to avoid the stuff in the upper left corner.', '2003-09-27 14:34:41.000000', NULL, 1),
(432491, 38283, 4210, '<td valign="top">Interesting composition. Great lighting.</td>', 'Interesting composition. Great lighting.', '2003-09-27 14:35:22.000000', NULL, 1),
(432492, 38483, 4210, '<td valign="top">Too much stuff going on in this photo.</td>', 'Too much stuff going on in this photo.', '2003-09-27 14:35:44.000000', NULL, 1),
(432493, 38975, 4210, '<td valign="top">Good colour, clarity. Interesting lighting.</td>', 'Good colour, clarity. Interesting lighting.', '2003-09-27 14:36:14.000000', NULL, 1),
(432494, 39009, 4210, '<td valign="top">Lacking in crispness of deatil.</td>', 'Lacking in crispness of deatil.', '2003-09-27 14:36:40.000000', NULL, 1),
(432495, 38971, 5728, '<td valign="top">Lovely pic, and an extra point for the title :-)</td>', 'Lovely pic, and an extra point for the title :-)', '2003-09-27 14:36:58.000000', NULL, 1),
(432496, 38052, 4210, '<td valign="top">Great colours and details.</td>', 'Great colours and details.', '2003-09-27 14:37:40.000000', NULL, 1),
(432497, 38678, 4210, '<td valign="top">Interesting colours. I don''t think the lighting works so well.</td>', 'Interesting colours. I don''t think the lighting works so well.', '2003-09-27 14:38:06.000000', NULL, 1),
(432498, 38726, 4210, '<td valign="top">I love the colours, abut I honestly think this would have been bettter without the bee.</td>', 'I love the colours, abut I honestly think this would have been bettter without the bee.', '2003-09-27 14:38:33.000000', NULL, 1),
(432499, 38774, 4210, '<td valign="top">Colours are so-so. Detail could be alot crisper.</td>', 'Colours are so-so. Detail could be alot crisper.', '2003-09-27 14:38:56.000000', NULL, 1),
(432500, 38687, 4210, '<td valign="top">Interesting, but some of the green on the left is destracting.</td>', 'Interesting, but some of the green on the left is destracting.', '2003-09-27 14:39:31.000000', NULL, 1),
(432501, 38853, 4210, '<td valign="top">Wow. Very narrow dof. I like it. Good job pulling it off.</td>', 'Wow. Very narrow dof. I like it. Good job pulling it off.', '2003-09-27 14:39:58.000000', NULL, 1),
(432502, 38281, 4210, '<td valign="top">I don''t like the narrow dof in this one. Composition is good though.</td>', 'I don''t like the narrow dof in this one. Composition is good though.', '2003-09-27 14:40:23.000000', NULL, 1),
(432503, 38239, 4210, '<td valign="top">Abstract, but doesn''t hold my interest. No fine details.</td>', 'Abstract, but doesn''t hold my interest. No fine details.', '2003-09-27 14:40:52.000000', NULL, 1),
(432504, 38129, 4210, '<td valign="top">Feels too crammed into the frame.</td>', 'Feels too crammed into the frame.', '2003-09-27 14:41:14.000000', NULL, 1),
(432514, 38982, 3540, '<td valign="top">I think a little more exposure and this would be in the ribbons.  Good creative shot.  I really like the concept.  Its just a smidge dark.  Nice work 9</td>', 'I think a little more exposure and this would be in the ribbons.  Good creative shot.  I really like the concept.  Its just a smidge dark.  Nice work 9', '2003-09-27 14:59:59.000000', NULL, 1),
(432515, 38873, 3540, '<td valign="top">The background is really well done on this shot.  The foreground looks just a bit out of focus.  Did you use Neatimage with this shot?  just curious, it sort of has that plastic look to it.</td>', 'The background is really well done on this shot.  The foreground looks just a bit out of focus.  Did you use Neatimage with this shot?  just curious, it sort of has that plastic look to it.', '2003-09-27 15:01:09.000000', NULL, 1),
(432517, 37984, 3540, '<td valign="top">Not particularly fond of this shot, as a macro.  Its not a bad shot at all.  Looks like a good retro type 60''s shot with the exposure and being black and white.</td>', 'Not particularly fond of this shot, as a macro.  Its not a bad shot at all.  Looks like a good retro type 60''s shot with the exposure and being black and white.', '2003-09-27 15:03:05.000000', NULL, 1),
(432518, 38134, 3540, '<td valign="top">I really like this shot.  The border is a good idea for this shot, just not sure about the color.  Nice work 9</td>', 'I really like this shot.  The border is a good idea for this shot, just not sure about the color.  Nice work 9', '2003-09-27 15:03:59.000000', NULL, 1),
(432526, 38721, 3540, '<td valign="top">Good color, nice crisp clean image.  Don''t like the blurred rock at the bottom so well.  But its not that bad.  Personally, I would''ve cropped the image just above that.  Good work tho 7</td>', 'Good color, nice crisp clean image.  Don''t like the blurred rock at the bottom so well.  But its not that bad.  Personally, I would''ve cropped the image just above that.  Good work tho 7', '2003-09-27 15:22:57.000000', NULL, 1),
(432541, 38011, 6870, '<td valign="top">Nice tones and composition! 9</td>', 'Nice tones and composition! 9', '2003-09-27 16:18:19.000000', NULL, 1),
(432542, 38935, 6870, '<td valign="top">Wonderful macro with lots of drama. 9</td>', 'Wonderful macro with lots of drama. 9', '2003-09-27 16:18:39.000000', NULL, 1),
(432544, 38807, 6870, '<td valign="top">I love the colors and background here! Nice, engaging shot. 9</td>', 'I love the colors and background here! Nice, engaging shot. 9', '2003-09-27 16:19:25.000000', NULL, 1),
(432545, 38477, 6870, '<td valign="top">Wow, we can even see Lincoln there! Nice close up! You might want to experiment with different points of view and cropping choices.</td>', 'Wow, we can even see Lincoln there! Nice close up! You might want to experiment with different points of view and cropping choices.', '2003-09-27 16:20:28.000000', NULL, 1),
(432547, 38874, 6870, '<td valign="top">Colors are kind of flat, but superb composition. This might also make a nice B/W image.</td>', 'Colors are kind of flat, but superb composition. This might also make a nice B/W image.', '2003-09-27 16:21:03.000000', NULL, 1),
(432548, 38005, 6870, '<td valign="top">Subtle contrasts work so well here. Well seen. 9</td>', 'Subtle contrasts work so well here. Well seen. 9', '2003-09-27 16:21:54.000000', NULL, 1),
(432549, 38109, 6870, '<td valign="top">Very moody and the grain seems to work well here.</td>', 'Very moody and the grain seems to work well here.', '2003-09-27 16:22:29.000000', NULL, 1),
(432550, 38724, 6870, '<td valign="top">Nice motion capture. The colored dots add much to this.</td>', 'Nice motion capture. The colored dots add much to this.', '2003-09-27 16:23:20.000000', NULL, 1),
(432551, 38924, 6870, '<td valign="top">Clarity here is fantastic,as is composition. 10</td>', 'Clarity here is fantastic,as is composition. 10', '2003-09-27 16:23:40.000000', NULL, 1),
(432552, 38667, 6870, '<td valign="top">YOur depth of field might be more effective if the foreground were in focus rather than the rear of the shot. Nice lines, textures and shapes here.</td>', 'YOur depth of field might be more effective if the foreground were in focus rather than the rear of the shot. Nice lines, textures and shapes here.', '2003-09-27 16:24:38.000000', NULL, 1),
(432553, 38939, 6870, '<td valign="top">Fun idea! Clever communication and nice execution. 9</td>', 'Fun idea! Clever communication and nice execution. 9', '2003-09-27 16:25:51.000000', NULL, 1),
(432555, 37984, 6870, '<td valign="top">Clever idea works with title!</td>', 'Clever idea works with title!', '2003-09-27 16:27:06.000000', NULL, 1),
(432556, 38856, 6870, '<td valign="top">Very pretty! Effective use of contrasts in color and line. 10</td>', 'Very pretty! Effective use of contrasts in color and line. 10', '2003-09-27 16:27:44.000000', NULL, 1),
(432557, 38982, 6870, '<td valign="top">Clever idea, if a little gross!</td>', 'Clever idea, if a little gross!', '2003-09-27 16:28:25.000000', NULL, 1),
(432558, 38278, 6870, '<td valign="top">Nice idea. Unique lighting and interplay of line and shadow here. 9</td>', 'Nice idea. Unique lighting and interplay of line and shadow here. 9', '2003-09-27 16:30:28.000000', NULL, 1),
(432561, 38655, 6870, '<td valign="top">Very dramatic shot with interesting textures and colors. I like! 10</td>', 'Very dramatic shot with interesting textures and colors. I like! 10', '2003-09-27 16:31:30.000000', NULL, 1),
(432562, 38425, 6870, '<td valign="top">Interesting light and shadow interplay. Wonderful clarity, too. 10</td>', 'Interesting light and shadow interplay. Wonderful clarity, too. 10', '2003-09-27 16:32:09.000000', NULL, 1),
(432563, 38623, 6870, '<td valign="top">Fun textures and interplay of light bouncing off of the bearings.</td>', 'Fun textures and interplay of light bouncing off of the bearings.', '2003-09-27 16:32:43.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(432564, 38836, 6870, '<td valign="top">NIce idea, perhaps a bit too dark,but composition is so nice with that curved shape swathing the right half of the image.</td>', 'NIce idea, perhaps a bit too dark,but composition is so nice with that curved shape swathing the right half of the image.', '2003-09-27 16:33:17.000000', NULL, 1),
(432565, 38296, 6870, '<td valign="top">Very fun and engaging abstract. 9</td>', 'Very fun and engaging abstract. 9', '2003-09-27 16:34:18.000000', NULL, 1),
(432566, 38859, 6870, '<td valign="top">Yummy! I like using fruits and veggies like stained glass. I hope to do a series; you can coach me! 9</td>', 'Yummy! I like using fruits and veggies like stained glass. I hope to do a series; you can coach me! 9', '2003-09-27 16:35:12.000000', NULL, 1),
(432567, 37864, 6870, '<td valign="top">Ribbit. Ribbit, ribbit, ribbit, croak, ribbit ribbit! Oh,and ribbit ribbit ribbit! 9</td>', 'Ribbit. Ribbit, ribbit, ribbit, croak, ribbit ribbit! Oh,and ribbit ribbit ribbit! 9', '2003-09-27 16:35:51.000000', NULL, 1),
(432568, 39006, 6870, '<td valign="top">I like the circle of highlights and the colors here! It may have been overprocessed, though. You may want to experiment with the radius of your Unsharp Mask.</td>', 'I like the circle of highlights and the colors here! It may have been overprocessed, though. You may want to experiment with the radius of your Unsharp Mask.', '2003-09-27 16:37:12.000000', NULL, 1),
(432570, 38474, 6870, '<td valign="top">LIghting is a bit harsh, but I so love the perspective ahnd details here.</td>', 'LIghting is a bit harsh, but I so love the perspective ahnd details here.', '2003-09-27 16:37:45.000000', NULL, 1),
(432571, 38721, 6870, '<td valign="top">Wonderful sharpness and clarity! 9</td>', 'Wonderful sharpness and clarity! 9', '2003-09-27 16:38:58.000000', NULL, 1),
(432572, 38832, 6870, '<td valign="top">B/W is an interesting choice relative to your title, which implies the food in all of its richness and glory (i.e. color). Nice details and lighting!</td>', 'B/W is an interesting choice relative to your title, which implies the food in all of its richness and glory (i.e. color). Nice details and lighting!', '2003-09-27 16:40:03.000000', NULL, 1),
(432585, 38807, 11907, '<td valign="top">Very nice and colorful. Surely a winner!</td>', 'Very nice and colorful. Surely a winner!', '2003-09-27 17:14:20.000000', NULL, 1),
(432640, 38733, 10084, '<td valign="top">Great touch of color in the flower really helps to add interst to the shot. Lighting makes the flower pop[ out of the shot. Really good details in the leaves.</td>', 'Great touch of color in the flower really helps to add interst to the shot. Lighting makes the flower pop[ out of the shot. Really good details in the leaves.', '2003-09-27 19:43:58.000000', NULL, 1),
(432642, 38474, 10084, '<td valign="top">Very cool picture of a sliced apple. Good composition helps to keep interest. Would like to see more lighting on the seeds to help make them pop out. You can see the details of the fiber in the apple. Frame works perfectly with the picture.</td>', 'Very cool picture of a sliced apple. Good composition helps to keep interest. Would like to see more lighting on the seeds to help make them pop out. You can see the details of the fiber in the apple. Frame works perfectly with the picture.', '2003-09-27 19:53:23.000000', NULL, 1),
(432676, 38474, 12311, '<td valign="top">Nice idea, but I think it would have worked better in color.  A little more definition in the seed area would help, too.  They''re a bit underexposed.</td>', 'Nice idea, but I think it would have worked better in color.  A little more definition in the seed area would help, too.  They''re a bit underexposed.', '2003-09-27 20:24:53.000000', NULL, 1),
(432677, 38628, 12311, '<td valign="top">Excellent composition, detail and color.  The tonal range is weel done, too.  About the only thing I''d change is to get a better view of the bee''s face.  ..But getting just this much is a real coup!</td>', 'Excellent composition, detail and color.  The tonal range is weel done, too.  About the only thing I''d change is to get a better view of the bee''s face.  ..But getting just this much is a real coup!', '2003-09-27 20:28:40.000000', NULL, 1),
(432679, 38739, 10402, '<td valign="top">Nice watch! And you''ve done great with the chain. I think the matches detract.</td>', 'Nice watch! And you''ve done great with the chain. I think the matches detract.', '2003-09-27 20:29:33.000000', NULL, 1),
(432680, 38686, 12311, '<td valign="top">Beautiful!  I do think a solid whit background would have been better here, however.</td>', 'Beautiful!  I do think a solid whit background would have been better here, however.', '2003-09-27 20:30:25.000000', NULL, 1),
(432682, 38870, 12311, '<td valign="top">Not bad, but not as interesting as it could be.  Perhaps more billowing, spiraling smoke would help.</td>', 'Not bad, but not as interesting as it could be.  Perhaps more billowing, spiraling smoke would help.', '2003-09-27 20:33:28.000000', NULL, 1),
(432683, 39009, 10402, '<td valign="top">Too closely cropped for my taste and a bit blurry.</td>', 'Too closely cropped for my taste and a bit blurry.', '2003-09-27 20:33:48.000000', NULL, 1),
(432684, 38465, 12311, '<td valign="top">The lighting is too uneven, with blown highlights at the top and lower left.</td>', 'The lighting is too uneven, with blown highlights at the top and lower left.', '2003-09-27 20:34:58.000000', NULL, 1),
(432685, 38181, 10402, '<td valign="top">Interesting perspective and nice lighting.</td>', 'Interesting perspective and nice lighting.', '2003-09-27 20:35:39.000000', NULL, 1),
(432686, 39001, 12311, '<td valign="top">Very nice subject and composition!</td>', 'Very nice subject and composition!', '2003-09-27 20:35:56.000000', NULL, 1),
(432687, 38998, 12311, '<td valign="top">Nice colors, but a wee bit overexposed in the center.</td>', 'Nice colors, but a wee bit overexposed in the center.', '2003-09-27 20:36:47.000000', NULL, 1),
(432689, 38873, 10402, '<td valign="top">Interesting shapes in a pleasing composition. The white halos around many of the edges are a sign of too much sharpening.</td>', 'Interesting shapes in a pleasing composition. The white halos around many of the edges are a sign of too much sharpening.', '2003-09-27 20:41:11.000000', NULL, 1),
(432690, 38724, 12311, '<td valign="top">Great shot!  I don''t recall ever seeing a macro that captures motion like this.</td>', 'Great shot!  I don''t recall ever seeing a macro that captures motion like this.', '2003-09-27 20:45:48.000000', NULL, 1),
(432693, 38722, 10402, '<td valign="top">Good tonal range. The brown petal edges show that the flower isn''t a new one, but it is still pretty. I don''t know who the title refers to, but the symbolism of photo suggests an older woman, past her prime, who enjoys giving of herself to help others.</td>', 'Good tonal range. The brown petal edges show that the flower isn''t a new one, but it is still pretty. I don''t know who the title refers to, but the symbolism of photo suggests an older woman, past her prime, who enjoys giving of herself to help others.', '2003-09-27 20:51:35.000000', NULL, 1),
(432694, 38967, 12311, '<td valign="top">Clear, simple, thought-provoking!  Nice!!</td>', 'Clear, simple, thought-provoking!  Nice!!', '2003-09-27 20:56:53.000000', NULL, 1),
(432695, 38222, 10402, '<td valign="top">Wow. The clarity and composition of this image really grab the viewer. The lines of the legs lead the eye to the head, which is nicely framed by the shell. Great photo.</td>', 'Wow. The clarity and composition of this image really grab the viewer. The lines of the legs lead the eye to the head, which is nicely framed by the shell. Great photo.', '2003-09-27 20:57:18.000000', NULL, 1),
(432696, 38338, 12311, '<td valign="top">Good one!  The cherry and the lips make it so!</td>', 'Good one!  The cherry and the lips make it so!', '2003-09-27 20:58:36.000000', NULL, 1),
(432698, 38760, 10402, '<td valign="top">Interesting composition and great colors, but a bit blurry and noisy.</td>', 'Interesting composition and great colors, but a bit blurry and noisy.', '2003-09-27 20:59:08.000000', NULL, 1),
(432699, 38721, 12311, '<td valign="top">A tough capture!  Great detail in the face.</td>', 'A tough capture!  Great detail in the face.', '2003-09-27 21:00:15.000000', NULL, 1),
(432700, 38283, 10402, '<td valign="top">The coin adds a nice contrast as well as giving an idea of the bug''s size. Great focus and lighting. I think it needs just a little more space at the top.</td>', 'The coin adds a nice contrast as well as giving an idea of the bug''s size. Great focus and lighting. I think it needs just a little more space at the top.', '2003-09-27 21:01:41.000000', NULL, 1),
(432701, 38904, 12311, '<td valign="top">Interesting.  But it leaves me sort of hanging - I can''t quite identify a mood, an object, or much of anything with it.</td>', 'Interesting.  But it leaves me sort of hanging - I can''t quite identify a mood, an object, or much of anything with it.', '2003-09-27 21:03:30.000000', NULL, 1),
(432702, 38836, 12311, '<td valign="top">It would have been better without the shape in the left center.</td>', 'It would have been better without the shape in the left center.', '2003-09-27 21:06:41.000000', NULL, 1),
(432703, 38853, 12311, '<td valign="top">It''s pink, alright!  Not a bad idea.</td>', 'It''s pink, alright!  Not a bad idea.', '2003-09-27 21:07:42.000000', NULL, 1),
(432704, 38670, 12311, '<td valign="top">I''ve often wondered what the inside of one of these flowers looked like - now I know.  Nice job!</td>', 'I''ve often wondered what the inside of one of these flowers looked like - now I know.  Nice job!', '2003-09-27 21:08:39.000000', NULL, 1),
(432705, 38827, 12311, '<td valign="top">Too much ground clutter.</td>', 'Too much ground clutter.', '2003-09-27 21:09:09.000000', NULL, 1),
(432706, 39001, 11283, '<td valign="top">Nice Chuck Berry Hair! Good photo, nice and crisp.</td>', 'Nice Chuck Berry Hair! Good photo, nice and crisp.', '2003-09-27 21:10:33.000000', NULL, 1),
(432707, 38739, 12311, '<td valign="top">Got a watch, ...er match?  Good composition, but you should have worked to get the matchbook and left side of the watch in focus.</td>', 'Got a watch, ...er match?  Good composition, but you should have worked to get the matchbook and left side of the watch in focus.', '2003-09-27 21:10:37.000000', NULL, 1),
(432708, 38949, 12311, '<td valign="top">Too blurry and over/under-exposed in certain areas.</td>', 'Too blurry and over/under-exposed in certain areas.', '2003-09-27 21:11:49.000000', NULL, 1),
(432709, 38892, 12311, '<td valign="top">Interesting.  I like the color on B&amp;W.</td>', 'Interesting.  I like the color on B&W.', '2003-09-27 21:13:12.000000', NULL, 1),
(432710, 38011, 12311, '<td valign="top">Nice one!  I just wish you had worked to get it all in even/sharp focus.</td>', 'Nice one!  I just wish you had worked to get it all in even/sharp focus.', '2003-09-27 21:14:29.000000', NULL, 1),
(432711, 38874, 11283, '<td valign="top">Some more light would have punched this up a bit IMHO but a nice photo just the same.</td>', 'Some more light would have punched this up a bit IMHO but a nice photo just the same.', '2003-09-27 21:14:36.000000', NULL, 1),
(432714, 38966, 12311, '<td valign="top">Nice!  Bravo!</td>', 'Nice!  Bravo!', '2003-09-27 21:15:08.000000', NULL, 1),
(432715, 38088, 10402, '<td valign="top">The diagonal lines make this image very dynamic. The black background for the white subject gives it impact.</td>', 'The diagonal lines make this image very dynamic. The black background for the white subject gives it impact.', '2003-09-27 21:15:29.000000', NULL, 1),
(432716, 38991, 11283, '<td valign="top">Very cool lighting gives this a fiery angry look. Nice photo.</td>', 'Very cool lighting gives this a fiery angry look. Nice photo.', '2003-09-27 21:16:46.000000', NULL, 1),
(432717, 38982, 12311, '<td valign="top">Yuk! ;-)  Great idea, but''s going to give me nightmares!</td>', 'Yuk! ;-)  Great idea, but''s going to give me nightmares!', '2003-09-27 21:17:29.000000', NULL, 1),
(432720, 38292, 10402, '<td valign="top">Nicely captures the metallic texture and interesting shape of the subject. The surface it is sitting contrasts nicely in color and texture.</td>', 'Nicely captures the metallic texture and interesting shape of the subject. The surface it is sitting contrasts nicely in color and texture.', '2003-09-27 21:21:03.000000', NULL, 1),
(432724, 38900, 10402, '<td valign="top">Interesting subject and good composition. The glint adds life. Needs a bit of sharpening.</td>', 'Interesting subject and good composition. The glint adds life. Needs a bit of sharpening.', '2003-09-27 21:25:51.000000', NULL, 1),
(432727, 38283, 12311, '<td valign="top">Nice capture!  The detail in both coin and bug is superb.  I rate this a nine for well-executed originality!</td>', 'Nice capture!  The detail in both coin and bug is superb.  I rate this a nine for well-executed originality!', '2003-09-27 21:29:12.000000', NULL, 1),
(432728, 38995, 12311, '<td valign="top">Good idea, but at least some of it should have been in focus.  Perhaps a little USM in Photoshop would have brought out the central flower.</td>', 'Good idea, but at least some of it should have been in focus.  Perhaps a little USM in Photoshop would have brought out the central flower.', '2003-09-27 21:30:37.000000', NULL, 1),
(432730, 38951, 12311, '<td valign="top">Neato!  I like it.</td>', 'Neato!  I like it.', '2003-09-27 21:31:23.000000', NULL, 1),
(432732, 38227, 12311, '<td valign="top">Original and well-executed!</td>', 'Original and well-executed!', '2003-09-27 21:31:56.000000', NULL, 1),
(432733, 38876, 12311, '<td valign="top">Good detail, sharpness and composition!</td>', 'Good detail, sharpness and composition!', '2003-09-27 21:32:32.000000', NULL, 1),
(432734, 38278, 11283, '<td valign="top">Great idea and nice lighting.</td>', 'Great idea and nice lighting.', '2003-09-27 21:33:22.000000', NULL, 1),
