(433263, 38665, 5705, '<td valign="top">OMG-- you guys are killing me with these awesome eye shots!! another 100--<br/> <br/> <br/>Good luck, but this one is gonna be a hard one to win-- very high scores</td>', 'OMG-- you guys are killing me with these awesome eye shots!! another 100--  Good luck, but this one is gonna be a hard one to win-- very high scores', '2003-09-28 21:16:08.000000', NULL, 1),
