(433288, 38832, 4871, '<td valign="top">And how many berries did you eat to get this shot? I love the reflection on the top. Great shot!</td>', 'And how many berries did you eat to get this shot? I love the reflection on the top. Great shot!', '2003-09-28 21:34:40.000000', NULL, 1),
(433294, 38476, 10084, '<td valign="top">Great closeup of a bug. The great depth of field helps to make it pop out of the picture. Great details in the hair. Incredible patterns on the bugs head.</td>', 'Great closeup of a bug. The great depth of field helps to make it pop out of the picture. Great details in the hair. Incredible patterns on the bugs head.', '2003-09-28 21:39:53.000000', NULL, 1),
